/* ============================================================
   Stable item sprites — no external URL text can leak into UI
   ============================================================ */
const ITEM_BASE='https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/';
const ITEM_SLUG={
'Pokéball':'poke-ball','Great Ball':'great-ball','Super Ball':'great-ball','Ultra Ball':'ultra-ball','Premier Ball':'premier-ball','Poção 50':'potion','Poção 100':'super-potion','Poção 200':'hyper-potion','Poção 30%':'fresh-water','Poção 50% HP':'moomoo-milk','Poção 100% HP':'max-potion',
'Fire Stone':'fire-stone','Water Stone':'water-stone','Leaf Stone':'leaf-stone','Thunder Stone':'thunder-stone','Ice Stone':'ice-stone','Punch Stone':'black-belt','Venom Stone':'poison-barb','Earth Stone':'soft-sand','Feather Stone':'sharp-beak','Enigma Stone':'twisted-spoon','Cocoon Stone':'silver-powder','Rock Stone':'hard-stone','Crystal Stone':'dragon-fang','Darkness Stone':'dusk-stone','Darkness Stone':'dusk-stone','Metal Stone':'metal-coat','Heart Stone':'shiny-stone','Heart Stone':'oval-stone','Shiny Stone':'shiny-stone','Boost Stone':'rare-candy','Fragmento Mega Stone':'key-stone',
'Essência Normal':'silk-scarf','Essência Fogo':'charcoal','Essência Água':'mystic-water','Essência Planta':'miracle-seed','Essência Elétrica':'magnet','Essência Gelo':'never-melt-ice','Essência Lutador':'black-belt','Essência Veneno':'poison-barb','Essência Terra':'soft-sand','Essência Voador':'sharp-beak','Essência Psíquica':'twisted-spoon','Essência Inseto':'silver-powder','Essência Pedra':'hard-stone','Essência Fantasma':'spell-tag','Essência Dragão':'dragon-fang','Essência Sombria':'black-glasses','Essência Metal':'metal-coat','Essência Fada':'fairy-feather','Belt of Champion':'black-belt',
'Rubber Ball':'poke-ball','Fur':'silk-scarf','Giant Piece Of Fur':'choice-band','Essence Of Fire':'heat-rock','Fire Tail':'red-card','Water Gem':'water-gem','Water Pendant':'sea-incense','Seed':'miracle-seed','Leaves':'big-root','Great Petal':'grassy-seed','Screw':'magnet','Electric Box':'cell-battery','Electric Rat Tail':'light-ball','Snowball':'snowball','Ice Orb':'icy-rock','Band Aid':'black-belt','Sandbag':'macho-brace','Belt Of Champion':'expert-belt','Punch Machine':'lucky-punch','Bottle Of Poison':'toxic-orb','Bug Venom':'poison-barb','Earth Ball':'smooth-rock','Piece Of Diglett':'soft-sand','Straw':'pretty-wing','Feather':'pretty-wing','Giant Beak':'sharp-beak','Enchanted Gem':'psychic-gem','Future Orb':'psychic-seed','Psychic Spoon':'twisted-spoon','Bug Gosme':'sticky-barb','Bug Antenna':'silver-powder','Small Stone':'hard-stone','Strange Rock':'float-stone','Ghost Essence':'spell-tag','Bat Wing':'dusk-stone','Dragon Scale':'dragon-scale','Dragon Tooth':'dragon-fang','Dark Gem':'dark-gem','Dark Ear':'black-glasses','Piece Of Steel':'metal-coat','Metal Hull':'iron-ball','Point Of Light':'bright-powder','Cute Ball':'pink-bow'
};
const ITEM_COLOR={fire:'#ef4444',water:'#38bdf8',grass:'#22c55e',electric:'#facc15',ice:'#67e8f9',fighting:'#f97316',poison:'#a855f7',ground:'#a16207',flying:'#93c5fd',psychic:'#d946ef',bug:'#84cc16',rock:'#78716c',ghost:'#8b5cf6',dragon:'#6366f1',dark:'#475569',steel:'#94a3b8',fairy:'#f9a8d4',normal:'#cbd5e1'};
function itemColor(n){n=String(n).toLowerCase();for(const [k,c] of Object.entries(ITEM_COLOR))if(n.includes(k)||({fire:'fogo',water:'água',grass:'planta',electric:'elétr',ice:'gelo',fighting:'lutador',poison:'veneno',ground:'terra',flying:'voador',psychic:'psíqu',bug:'inseto',rock:'pedra',ghost:'fantasma',dragon:'dragão',dark:'sombr',steel:'metal',fairy:'fada',normal:'normal'}[k]&&n.includes({fire:'fogo',water:'água',grass:'planta',electric:'elétr',ice:'gelo',fighting:'lutador',poison:'veneno',ground:'terra',flying:'voador',psychic:'psíqu',bug:'inseto',rock:'pedra',ghost:'fantasma',dragon:'dragão',dark:'sombr',steel:'metal',fairy:'fada',normal:'normal'}[k])))return c;return'#64748b'}
W.psy20ItemFallback=function(img,name){const sp=D.createElement('span');sp.className='psy20-fallback';sp.style.setProperty('--ic',itemColor(name));sp.textContent=String(name||'?').trim().slice(0,2).toUpperCase();img.replaceWith(sp)};
W.psyV11ItemIconUrl=function(name){return W.PSY_ITEMS?.url(name)||''};
W.psyV11ItemIcon=function(name,alt=''){return W.PSY_ITEMS?.html(name,alt)||`<span class="psy20-fallback" style="--ic:${itemColor(name)}">${esc(String(name||'?').slice(0,2).toUpperCase())}</span>`};
W.v12ItemIcon=n=>W.psyV11ItemIcon(n);W.v12ShopIcon=n=>W.psyV11ItemIcon(n);
try{v12ItemIcon=W.v12ItemIcon;v12ShopIcon=W.v12ShopIcon;psyV11ItemIcon=W.psyV11ItemIcon;psyV11ItemIconUrl=W.psyV11ItemIconUrl}catch(e){}

/* ============================================================
   Darkness Stone removed; only ordinary Stones are sellable
   ============================================================ */
const SELL_STONES=new Set(['Fire Stone','Water Stone','Leaf Stone','Thunder Stone','Ice Stone','Punch Stone','Venom Stone','Earth Stone','Feather Stone','Enigma Stone','Cocoon Stone','Rock Stone','Crystal Stone','Darkness Stone','Metal Stone','Heart Stone','Heart Stone']);
function migrateGhost(){core();
  const q=Number(P.inventory['Ghost Stone']||0)+Number(P.inventory['Dark Stone']||0);
  if(q)P.inventory['Darkness Stone']=Number(P.inventory['Darkness Stone']||0)+q;
  delete P.inventory['Ghost Stone'];delete P.inventory['Dark Stone'];
  try{if(typeof EVOLUTION_MAP!=='undefined')for(const e of Object.values(EVOLUTION_MAP||{}))if(e&&['Ghost Stone','Dark Stone'].includes(e.stone))e.stone='Darkness Stone'}catch(e){}
  try{if(typeof TYPE_TO_STONE!=='undefined'){TYPE_TO_STONE.Fantasma='Darkness Stone';TYPE_TO_STONE.Ghost='Darkness Stone';TYPE_TO_STONE.Sombrio='Darkness Stone';TYPE_TO_STONE.Noturno='Darkness Stone';TYPE_TO_STONE.Dark='Darkness Stone'}}catch(e){}
  try{if(typeof SHOP_DG!=='undefined'&&Array.isArray(SHOP_DG)){for(let i=SHOP_DG.length-1;i>=0;i--)if(['Ghost Stone','Dark Stone'].includes(SHOP_DG[i]?.n))SHOP_DG.splice(i,1);if(!SHOP_DG.some(x=>x?.n==='Darkness Stone'))SHOP_DG.push({n:'Darkness Stone',p:20000,t:'stone',i:'🌑',d:'Fantasma / Sombrio'})}}catch(e){}
}
function stonePrice(n){if(!SELL_STONES.has(n))return 0;try{const it=SHOP_DG.find(x=>x.n===n);if(it?.p)return Math.max(1,Math.floor(it.p*.5))}catch(e){}return 15000}
W.psyV11SellPrice=n=>stonePrice(String(n));W.psyV10SellPrice=W.psyV11SellPrice;
W.psyV11ShopSellables=function(){core();return Object.entries(P.inventory).filter(([n,q])=>q>0&&SELL_STONES.has(n)).sort((a,b)=>a[0].localeCompare(b[0]))};
W.psyV11SellItem=function(n,q=1){core();n=String(n);if(!SELL_STONES.has(n))return toast('Somente Stones elementais comuns podem ser vendidas.');const own=Number(P.inventory[n]||0),qty=clamp(Number(q)||1,1,own),price=stonePrice(n);if(!own||!price)return;P.inventory[n]-=qty;if(P.inventory[n]<=0)delete P.inventory[n];P.gold=Number(P.gold||0)+price*qty;save();toast(`💰 ${qty}x ${n}: +${fmt(price*qty)} Gold`);try{W.psyV11RenderShopSell?.()}catch(e){}};
function renderSellOnlyStones(host){const arr=W.psyV11ShopSellables();host.innerHTML=`<div class="psy20-sellgrid">${arr.length?arr.map(([n,q])=>`<div class="psy20-sell">${W.psyV11ItemIcon(n)}<b>${esc(n)}</b><div style="color:#facc15">x${fmt(q)}</div><small>${fmt(stonePrice(n))} Gold cada</small><div class="psy20-row" style="margin-top:7px"><button class="psy20-btn gold" onclick="psyV11SellItem('${esc(n)}',1)">VENDER 1</button><button class="psy20-btn" onclick="psyV11SellItem('${esc(n)}',${Number(q)})">TODAS</button></div></div>`).join(''):'<div class="psy20-card">Você não possui Stones comuns vendáveis.</div>'}</div>`}
W.psyV11RenderShopSell=function(){const g=$('shop-grid');if(!g)return;g.style.cssText='max-height:62vh;overflow:auto;padding:8px';renderSellOnlyStones(g);const detail=$('shop-detail');if(detail)detail.innerHTML='<b>Venda segura:</b> somente Stones elementais comuns podem ser vendidas. Materiais de Craft, Quests e itens raros ficam protegidos.';const b=$('btn-buy');if(b)b.style.display='none'};
W.openBagSellV10=function(){let s=$('psy20-sell-screen');if(!s){s=D.createElement('div');s.id='psy20-sell-screen';s.className='psy20-overlay';D.body.appendChild(s)}s.style.display='flex';s.innerHTML=`<div class="psy20-panel" style="width:min(900px,96vw)"><button class="psy20-close" onclick="document.getElementById('psy20-sell-screen').style.display='none'">×</button><h2 class="psy20-title">🪨 VENDER STONES</h2><div class="psy20-sub">Materiais de Craft e de Quests nunca aparecem nesta lista. Shiny Stone, Boost Stone e Fragmento Mega Stone também são protegidos.</div><div id="psy20-bagsell" style="margin-top:10px"></div></div>`;renderSellOnlyStones($('psy20-bagsell'))};
try{openBagSellV10=W.openBagSellV10}catch(e){}

/* craft materials are their own inventory family; quest loot stays separate */
W.renderCraft5=function(){const el=$('craft5-list');if(!el)return;const seen=new Set();const entries=[];try{for(const [k,e] of Object.entries(PSY_ELEMENT_DATA||{})){if(!e?.ess||seen.has(e.ess))continue;seen.add(e.ess);entries.push([k,e])}}catch(e){}el.innerHTML=entries.map(([k,e])=>`<div class="psy-craft5" style="--c:${e.color}"><div class="psy-craft-flow"><span>${W.psyV11ItemIcon(e.ess)}</span><b>10x</b><i>→</i><span>${W.psyV11ItemIcon(e.ball)}</span><b>1x</b></div><div><h3>${esc(e.ball)}</h3><div class="psy-desc">Use 10 ${esc(e.ess)} para fabricar 1 ${esc(e.ball)}.</div><div class="psy-craft-stock"><span>Material <b>${fmt(P.inventory[e.ess]||0)}/10</b></span><span>Na bolsa <b>${fmt(P.inventory[e.ball]||0)}</b></span></div></div><button ${Number(P.inventory[e.ess]||0)<10?'disabled':''} onclick="psyCraftElementBall('${esc(k)}')">FABRICAR</button></div>`).join('')};

/* ============================================================
   Point 1: map boundaries + dynamic/invisible joystick
   ============================================================ */
function cityBounds(){try{const mw=Number(typeof MAP_W!=='undefined'?MAP_W:(map?.[0]?.length||1)),mh=Number(typeof MAP_H!=='undefined'?MAP_H:(map?.length||1));if(!mw||!mh)return;const ox=Number(P.x||0),oy=Number(P.y||0);P.x=clamp(ox,0,mw-1);P.y=clamp(oy,0,mh-1);P.tx=clamp(Number(P.tx??P.x),0,mw-1);P.ty=clamp(Number(P.ty??P.y),0,mh-1);const row=map?.[P.ty],tile=row?.[P.tx];const invalid=!row||typeof tile==='undefined'||P.tx<0||P.ty<0||P.tx>=mw||P.ty>=mh;if(invalid){P.tx=P.x;P.ty=P.y;P.moving=false}if(P.x!==ox||P.y!==oy||!P.moving){P.px=P.x*Number(typeof TILE!=='undefined'?TILE:32);P.py=P.y*Number(typeof TILE!=='undefined'?TILE:32)}}catch(e){}}
try{const cityUpdateBase=W.update||update;W.update=function(dt){const r=cityUpdateBase?.apply(this,arguments);cityBounds();return r};update=W.update}catch(e){}
function djoy(id){let j=$(id);if(!j){j=D.createElement('div');j.id=id;j.className='psy20-djoy';j.innerHTML='<i></i>';D.body.appendChild(j)}return j}
function moveDjoy(j,cx,cy,dx,dy,max=44){j.style.left=cx+'px';j.style.top=cy+'px';j.classList.add('show');const l=Math.hypot(dx,dy)||1,k=Math.min(max,l),x=dx/l*k,y=dy/l*k;j.querySelector('i').style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`}
function hideDjoy(j){j?.classList.remove('show');if(j?.querySelector('i'))j.querySelector('i').style.transform='translate(-50%,-50%)'}
function installCityDynamicJoy(){const s=$('game-wrap');if(!s||s.dataset.psy20joy)return;s.dataset.psy20joy='1';const joy=djoy('psy20-city-joy');let pid=null,ox=0,oy=0;const apply=(dx,dy)=>{try{const l=Math.hypot(dx,dy)||1,nx=dx/l,ny=dy/l;keys['ArrowLeft']=nx<-.28;keys['ArrowRight']=nx>.28;keys['ArrowUp']=ny<-.28;keys['ArrowDown']=ny>.28}catch(e){}};const clear=()=>{try{keys['ArrowLeft']=keys['ArrowRight']=keys['ArrowUp']=keys['ArrowDown']=false}catch(e){}};s.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'||e.target.closest('button,input,select,#hud-player,#menu'))return;if(e.clientX>innerWidth*.75)return;pid=e.pointerId;ox=e.clientX;oy=e.clientY;s.setPointerCapture?.(pid);moveDjoy(joy,ox,oy,0,0);apply(0,0)},{passive:true});s.addEventListener('pointermove',e=>{if(e.pointerId!==pid)return;const dx=e.clientX-ox,dy=e.clientY-oy;apply(dx,dy);moveDjoy(joy,ox,oy,dx,dy)},{passive:true});const end=e=>{if(e.pointerId!==pid)return;pid=null;clear();hideDjoy(joy)};s.addEventListener('pointerup',end);s.addEventListener('pointercancel',end)}
function installWorldDynamicJoy(){const s=$('screen-world');if(!s||s.dataset.psy20joy)return;s.dataset.psy20joy='1';const joy=djoy('psy20-world-joy');let pid=null,ox=0,oy=0,lastX=0;
s.addEventListener('pointerdown',e=>{if(!inWorld||e.pointerType==='mouse'||e.target.closest('button,input,select,.psy20-overlay'))return;if(pid!==null)return;pid=e.pointerId;s.setPointerCapture?.(pid);if(e.clientX<innerWidth*.62){ox=e.clientX;oy=e.clientY;moveDjoy(joy,ox,oy,0,0);joy.dataset.mode='move'}else{lastX=e.clientX;joy.dataset.mode='look'}},{passive:true});
s.addEventListener('pointermove',e=>{if(e.pointerId!==pid||!inWorld)return;if(joy.dataset.mode==='move'){const dx=e.clientX-ox,dy=e.clientY-oy,l=Math.hypot(dx,dy)||1,m=60,k=Math.min(m,l);joyMoveX=(dx/l*k)/m;joyMoveY=-(dy/l*k)/m;moveDjoy(joy,ox,oy,dx,dy)}else{const dx=e.clientX-lastX;lastX=e.clientX;try{worldPlayer.angle+=dx*(Number(camSens||.0025)*1.25)}catch(x){}}},{passive:true});
const end=e=>{if(e.pointerId!==pid)return;pid=null;try{joyMoveX=0;joyMoveY=0}catch(x){}hideDjoy(joy)};s.addEventListener('pointerup',end);s.addEventListener('pointercancel',end)}
function clampWorld(){try{if(!inWorld||!worldPlayer)return;worldPlayer.x=clamp(Number(worldPlayer.x||SAFE_X),1.25,Number(WORLD_W||120)-1.25);worldPlayer.y=clamp(Number(worldPlayer.y||SAFE_Y),1.25,Number(WORLD_H||120)-1.25);const row=worldMap?.[Math.floor(worldPlayer.y)],tile=row?.[Math.floor(worldPlayer.x)];if(tile!==0&&tile!==3){worldPlayer.x=clamp(Number(SAFE_X||60)+.5,1.25,Number(WORLD_W||120)-1.25);worldPlayer.y=clamp(Number(SAFE_Y||60)+.5,1.25,Number(WORLD_H||120)-1.25)}}catch(e){}}
function survKeys(dx,dy){try{const l=Math.hypot(dx,dy)||1,nx=dx/l,ny=dy/l;V12_SURV_KEYS.a=nx<-.27;V12_SURV_KEYS.d=nx>.27;V12_SURV_KEYS.w=ny<-.27;V12_SURV_KEYS.s=ny>.27}catch(e){}}
function clearSurvKeys(){try{['a','d','w','s','arrowleft','arrowright','arrowup','arrowdown'].forEach(k=>V12_SURV_KEYS[k]=false)}catch(e){}}
function installSurvDynamicJoy(){const s=$('screen-survivor-v12');if(!s||s.dataset.psy20joy)return;s.dataset.psy20joy='1';const joy=djoy('psy20-surv-joy');let pid=null,ox=0,oy=0;
s.addEventListener('pointerdown',e=>{if(!W.V12_SURV||e.pointerType==='mouse'||e.target.closest('button,#v13-surv-pause,#v12-surv-up'))return;if(e.clientX>innerWidth*.72)return;pid=e.pointerId;ox=e.clientX;oy=e.clientY;s.setPointerCapture?.(pid);moveDjoy(joy,ox,oy,0,0);survKeys(0,0)},{passive:true});
s.addEventListener('pointermove',e=>{if(e.pointerId!==pid||!W.V12_SURV)return;const dx=e.clientX-ox,dy=e.clientY-oy;survKeys(dx,dy);moveDjoy(joy,ox,oy,dx,dy)},{passive:true});const end=e=>{if(e.pointerId!==pid)return;pid=null;clearSurvKeys();hideDjoy(joy)};s.addEventListener('pointerup',end);s.addEventListener('pointercancel',end)}
const survStartBase=W.v12StartSurvivor;W.v12StartSurvivor=function(){const r=survStartBase?.apply(this,arguments);setTimeout(()=>{installSurvDynamicJoy();clearSurvKeys()},30);return r};try{v12StartSurvivor=W.v12StartSurvivor}catch(e){}
W.v13ExitSurvivor=function(){clearSurvKeys();const p=$('v13-surv-pause');p?.classList.remove('show');const s=W.V12_SURV;if(s){s.paused=false;try{W.v12FinishSurvivor(false,true)}catch(e){console.error(e);s.done=true;W.V12_SURV=null;$('screen-survivor-v12')?.style&&( $('screen-survivor-v12').style.display='none');W.openPsyduckDungeon5?.()}}else{const sc=$('screen-survivor-v12');if(sc)sc.style.display='none';W.openPsyduckDungeon5?.()}};

/* ============================================================
   Point 2: Psyduck tree uses Gold; Trials pay PsyCoin once
   ============================================================ */
const SKILL_WEIGHT={power:1.35,rate:1.25,hp:1.10,speed:1.0,helper:1.35,nova:1.50,magnet:.9,crit:1.2,regen:1.25,pierce:1.4,multi:1.4};
function psySkillCost(k,lv){return Math.ceil((10000*(SKILL_WEIGHT[k]||1)*Math.pow(lv+1,1.35))/500)*500}
W.v12BuyPsySkill=function(k){core();let ps,d;try{ps=v12PsyTreeEnsure();d=V12_PSY_TREE[k]}catch(e){}const lv=Number(ps?.survSkills?.[k]||0);if(!ps||!d||lv>=d.max)return;const cost=psySkillCost(k,lv);if(Number(P.gold||0)<cost)return toast(`Precisa ${fmt(cost)} Gold.`);P.gold-=cost;ps.survSkills[k]=lv+1;ps.survSkillPoints=0;save();try{v12PsyTab('tree')}catch(e){W.openPsyduckDungeon5?.()}};
W.v12RenderPsyTree=function(c){core();let ps;try{ps=v12PsyTreeEnsure();ps.survSkillPoints=0}catch(e){}if(!c||!ps)return;c.innerHTML=`<div class="psy20-card"><h3 style="margin:0;color:#facc15">🌟 ÁRVORE EXCLUSIVA — PSYDUCK SURVIVOR</h3><div class="psy20-sub">As habilidades agora são compradas com <b>Gold</b>. Provações não fornecem pontos da árvore.</div></div><div class="psy20-tree" style="margin-top:9px">${Object.entries(typeof V12_PSY_TREE!=='undefined'?V12_PSY_TREE:{}).map(([k,x])=>{const lv=Number(ps.survSkills[k]||0),cost=psySkillCost(k,lv);return`<div class="psy20-tree-card"><h4>${esc(x.n)} • ${lv}/${x.max}</h4><div class="psy20-sub" style="min-height:34px">${esc(x.d)}</div><button class="psy20-btn purple" style="width:100%;margin-top:8px" ${lv>=x.max?'disabled':''} onclick="v12BuyPsySkill('${esc(k)}')">${lv>=x.max?'MÁXIMO':`UP • ${fmt(cost)} Gold`}</button></div>`}).join('')}</div>`};
try{v12RenderPsyTree=W.v12RenderPsyTree}catch(e){}
function trialPhase(i){try{return Number(V13_TRIAL_PHASES?.[i]||0)}catch(e){return i===19?200:Math.max(1,i*10)}}
function trialBaseReward(i){try{return Number(V13_TRIAL_REWARD?.[i]?.gold||30000+(i*18000))}catch(e){return 30000+i*18000}}
W.v12RenderTrials=function(c){core();let p,ps;try{p=v12EnsurePsyduck();ps=v12PsyTreeEnsure()}catch(e){}if(!p||!ps||!c)return;ps.survSkillPoints=0;const r=Number(p.resets||0),best=Number(ps.survivorBest||0),trials=typeof V12_PSY_TRIALS!=='undefined'?V12_PSY_TRIALS:[];c.innerHTML=`<div class="psy20-card"><h3 style="margin:0;color:#facc15">🏆 PROVAÇÕES DA ASCENSÃO</h3><div class="psy20-sub">Cada Provação concede <b>1 PsyCoin somente na primeira conclusão</b>, além do Gold do marco. Não existe farm infinito de PsyCoin.</div></div><div class="psy20-trials" style="margin-top:9px">${trials.map((need,i)=>{const phase=trialPhase(i),id='t'+(i+1),done=!!ps.trialsDone?.[id],open=r>=need&&best>=phase;return`<div class="psy20-trial ${done?'done':open?'open':''}"><b>Prova ${i+1}</b><div>Reset ${need} • Survivor Fase ${phase}</div><small style="display:block;color:#9bb7da;margin:6px 0">Prêmio: ${fmt(trialBaseReward(i))} Gold + 💠 1 PsyCoin${(i+1)%4===0?' + 1 PsyStone':''}${(i+1)%5===0?' + 1 Pack Raro':''}${i===19?' • Forma SQUIZO':''}</small><button class="psy20-btn ${open&&!done?'gold':''}" ${!open||done?'disabled':''} onclick="v12ClaimPsyTrial(${i+1})">${done?'CONCLUÍDA':open?'CONCLUIR PROVA':'🔒 BLOQUEADA'}</button></div>`}).join('')}</div>`};try{v12RenderTrials=W.v12RenderTrials}catch(e){}
W.v12ClaimPsyTrial=function(n){core();let p,ps;try{p=v12EnsurePsyduck();ps=v12PsyTreeEnsure()}catch(e){}const i=Number(n)-1,trials=typeof V12_PSY_TRIALS!=='undefined'?V12_PSY_TRIALS:[],need=Number(trials[i]),phase=trialPhase(i),id='t'+n;if(!p||!ps||i<0||i>=trials.length)return;if(ps.trialsDone?.[id])return toast(`Prova ${n} já concluída.`);if(Number(p.resets||0)<need||Number(ps.survivorBest||0)<phase)return toast(`Requer Reset ${need} e Survivor Fase ${phase}.`);ps.trialsDone=ps.trialsDone||{};ps.trialsDone[id]=true;ps.survSkillPoints=0;P.meta.psy20TrialCoinPaid=P.meta.psy20TrialCoinPaid||{};P.meta.psy20TrialCoinPaid[id]=1;P.gold=Number(P.gold||0)+trialBaseReward(i);P.psycoin=Number(P.psycoin||0)+1;if((i+1)%4===0)P.inventory.PsyStone=Number(P.inventory.PsyStone||0)+1;if((i+1)%5===0)P.cardGame.packs.rare=Number(P.cardGame.packs.rare||0)+1;save();toast(`🏆 Prova ${n}: +${fmt(trialBaseReward(i))} Gold + 1 PsyCoin`,3600);try{v12PsyTab('trials')}catch(e){}};
W.v12PsyTutorial=function(){let s=$('psy20-psy-tutorial');if(!s){s=D.createElement('div');s.id='psy20-psy-tutorial';s.className='psy20-overlay';D.body.appendChild(s)}s.style.display='flex';s.innerHTML=`<div class="psy20-panel" style="width:min(940px,96vw);max-height:90vh;overflow:auto"><button class="psy20-close" onclick="document.getElementById('psy20-psy-tutorial').style.display='none'">×</button><h2 class="psy20-title">🦆 TUTORIAL — PSYDUCK SUPREMO</h2><div class="psy20-card" style="margin-top:10px;line-height:1.65"><h3 style="margin-top:0;color:#67e8f9">🎮 SURVIVOR</h3><ul><li>Cada fase começa no <b>Run Lv.1</b>. A EXP da run entra diretamente ao derrotar inimigos; não existem orbes de EXP no chão.</li><li>Ao subir o Run Level aparecem <b>5 Power-Ups</b>. Treino Intensivo concede +10% de EXP da run por nível, até 5/5.</li><li>Move Speed vem somente de Power-Up. Há no máximo <b>3 ajudantes</b> e <b>3 habilidades do Psyduck</b> por run.</li><li>O HP dos inimigos cresce com o tempo. Shiny, Mega, Mega Shiny, Elites e Bosses aparecem como ameaças especiais.</li><li>O Elite periódico concede uma escolha especial ao ser derrotado. Bosses concedem uma nova seleção de Power-Ups. A fase dura 10 minutos: Elites aparecem a cada 1m30, Bosses entram aos 3, 6 e 9 minutos, e o Boss final surge no minuto 10. A fase só termina quando o Boss final for derrotado; Pokémon normais e spawns especiais continuam entrando enquanto houver chefe vivo.</li><li>No computador, use <b>WASD ou Setas</b> para mover e <b>ESC</b> para pausar/continuar. Em telas touch, use o joystick dinâmico.</li><li>Ao pausar, use <b>CIDADE</b> para congelar e salvar a run, voltar ao jogo principal e retornar ao Survivor depois sem perder progresso. Na tela de retomada, <b>DEPOIS</b> fecha o aviso sem apagar a run salva.</li></ul><div class="psy20-card" style="margin:12px 0;border-color:#facc15;background:#2a210d"><b style="color:#fde047">💡 DICA:</b> Caso não esteja conseguindo causar dano o suficiente, não desanime. Você pode entrar na fase novamente com os status melhorados, pois o Survivor sincroniza <b>10% do HP</b> e <b>5% do ataque</b> do seu Psyduck real.</div><h3 style="color:#facc15">🤝 AJUDANTES E FORMAS</h3><ul><li><b>Pikachu:</b> raios. <b>Lapras:</b> cones de gelo. <b>Dragonite:</b> tornados. <b>Slowpoke:</b> jatos de água. <b>Gengar:</b> buracos negros. <b>Charizard:</b> meteoros.</li><li>A evolução de combate durante cada partida acontece pelos Power-Ups escolhidos na própria run.</li><li>Os ajudantes mudam visualmente conforme evoluem: Lv.3 usa forma Shiny, Lv.5 usa Mega e MAX usa Shiny Mega quando a forma existir. Charizard escolhe uma de suas formas Mega na run.</li><li>O MAX de cada ajudante exige também um Power-Up relacionado no nível necessário, então não basta apenas elevar o ajudante rapidamente.</li></ul><h3 style="color:#4ade80">📦 DROPS E PROGRESSÃO DA RUN</h3><ul><li>Gold e EXP são entregues pelas derrotas e escalam com a força do inimigo e a progressão da fase.</li><li><b>Itens de inventário não ficam espalhados no chão:</b> Stones, Shiny Stone, Fragmento Mega Stone, Packs e demais drops de inventário são enviados diretamente para a Bag e geram um alerta na tela. O histórico da run pode ser consultado na pausa.</li><li>A cada marco de <b>1.000 Pokémon derrotados</b>, você recebe uma Stone evolutiva comum aleatória diretamente na Bag. Shiny Stone e Fragmento Mega Stone não entram nesse sorteio e possuem seus próprios sistemas de drop e pity.</li><li>Buffs globais compatíveis de Dano, Gold, XP e Drop continuam sendo considerados no Survivor.</li><li>Shiny e Mega derrotados podem fortalecer cumulativamente os atributos da run.</li></ul><h3 style="color:#fb7185">👹 ELITES E BOSSES</h3><ul><li>Elites entram periodicamente e possuem resistência superior aos inimigos comuns.</li><li>Bosses usam ataques especiais com <b>indicadores vermelhos no chão</b>, incluindo meteoros, tiros, investidas e armadilhas. Saia da área marcada antes do impacto.</li><li>Os valores internos de spawn, HP e chances de drop não são exibidos; observe os alertas e adapte sua build durante a run.</li></ul><h3 style="color:#f472b6">🧬 PSYDUCK REAL E BUFFS</h3><ul><li>Parte dos atributos do Psyduck real é sincronizada ao iniciar a fase, tornando o crescimento fora da run relevante para novas tentativas.</li><li><b>A cada 10 níveis reais do Psyduck</b>, ele inicia o Survivor com <b>+1 Perfuração e +1 Rajada</b>. Esse bônus é permanente enquanto o Psyduck estiver naquele nível real e soma com os Power-Ups obtidos durante a run.</li><li>Treino Intensivo acelera somente a progressão de Run Level; ele não aumenta a EXP recebida pelo Psyduck real.</li></ul><h3 style="color:#c084fc">🏆 PROVAÇÕES, ASCENSÃO E FORMAS</h3><ul><li><b>Reset e Provações são sistemas separados.</b> O Reset exige Lv.100 + Gold, concede <b>+10% permanente em todos os atributos</b> e <b>+1 PsyCoin</b>, até o limite de <b>999 Resets</b>.</li><li>As <b>24 Provações</b> são runs exclusivas liberadas por marcos de Reset. A ordem alterna <b>Tier primeiro</b> e depois <b>Qualidade</b>: começa em Tier E → D e depois Qualidade Lixo → Quase Lixo.</li><li>A progressão exclusiva do Psyduck termina em <b>Qualidade SQUIZO</b>, acima de OBLIVION, e <b>Tier SP</b>, acima de UR++. A Qualidade SQUIZO fica disponível no marco de <b>Reset 200</b>. Depois do Reset 200, a curva de EXP e Gold fica mais pesada.</li><li>O Psyduck especial continua ligado ao sistema Supremo e não vem de Eggs.</li></ul></div></div>`};
try{v12PsyTutorial=W.v12PsyTutorial}catch(e){}
const survFinishBase2=W.v12FinishSurvivor;W.v12FinishSurvivor=function(){let ps;try{ps=v12PsyTreeEnsure();if(ps)ps.survSkillPoints=0}catch(e){}const r=survFinishBase2?.apply(this,arguments);try{ps=v12PsyTreeEnsure();if(ps)ps.survSkillPoints=0}catch(e){}setTimeout(()=>{D.querySelectorAll('.psy-v12-surv-result,.psy-v11-surv-result').forEach(x=>{x.innerHTML=x.innerHTML.replace(/\s*•\s*\+2 pontos da Árvore/gi,'').replace(/Pack Cards Normal/gi,'Pack Normal')})},10);return r};try{v12FinishSurvivor=W.v12FinishSurvivor}catch(e){}

/* ============================================================
   VIP — PokeTibia-inspired
   ============================================================ */
const VIP_PLANS=[{d:5,p:3},{d:7,p:5},{d:30,p:10},{d:60,p:15},{d:90,p:25}];
function vipUntil(){core();return Number(P.meta.vipUntil||0)}function vipOn(){return vipUntil()>Date.now()}function vipRemain(){const ms=Math.max(0,vipUntil()-Date.now()),d=Math.floor(ms/86400000),h=Math.floor(ms%86400000/3600000);return d?`${d}d ${h}h`:`${h}h`}
W.psy20BuyVip=function(days,price){core();days=Number(days);price=Number(price);if(!VIP_PLANS.some(x=>x.d===days&&x.p===price))return;if(P.psycoin<price)return toast(`Precisa ${price} PsyCoin.`);P.psycoin-=price;P.meta.vipUntil=Math.max(Date.now(),vipUntil())+days*86400000;save();toast(`⭐ VIP ativado por ${days} dias!`,3500);W.openVIP()};
W.openVIP=function(){core();let s=$('psy20-vip');if(!s){s=D.createElement('div');s.id='psy20-vip';s.className='psy20-overlay';D.body.appendChild(s)}s.style.display='flex';s.innerHTML=`<div class="psy20-panel"><button class="psy20-close" onclick="document.getElementById('psy20-vip').style.display='none'">×</button><div class="psy20-viphero"><img src="https://play.pokemonshowdown.com/sprites/ani/psyduck.gif"><div><h2 class="psy20-title" style="color:#facc15">⭐ VIP PSYWORLD</h2><div class="psy20-sub">Benefícios ativos em todo o jogo: <b>+20% chance de captura • +50% loot • +50% XP</b>.</div><div style="margin-top:10px;font-weight:900;color:${vipOn()?'#86efac':'#fb7185'}">${vipOn()?`VIP ATIVO • ${vipRemain()} restantes`:'VIP INATIVO'}</div><div style="margin-top:6px;color:#d8b4fe">Saldo: 💠 ${fmt(P.psycoin)} PsyCoin</div></div></div><div class="psy20-vipgrid">${VIP_PLANS.map(x=>`<div class="psy20-vipplan"><h3>${x.d} DIAS</h3><div style="font-size:25px;color:#d8b4fe;font-weight:1000">💠 ${x.p}</div><button class="psy20-btn gold" style="width:100%;margin-top:9px" onclick="psy20BuyVip(${x.d},${x.p})">ATIVAR</button></div>`).join('')}</div></div>`};
const buffBase=W.getTotalBuff;W.getTotalBuff=function(k){const b=Number(buffBase?.apply(this,arguments)||0);if(!vipOn())return b;if(k==='xp'||k==='drop')return b+50;if(k==='cap')return b+20;return b};try{getTotalBuff=W.getTotalBuff}catch(e){}
try{const capBase=W.psyTierCaptureBase||psyTierCaptureBase;W.psyTierCaptureBase=function(t){return Number(capBase(t))* (vipOn()?1.2:1)};psyTierCaptureBase=W.psyTierCaptureBase}catch(e){}

/* ============================================================
   Battle Pass — exact approved structure, 100 levels
   ============================================================ */
const PASS_MAX=100,PASS_XP_LEVEL=1000,PASS_TOTAL=100000,PASS_DAILY_CAP=7000,PASS_DAYS=45;
const PASS_TYPES=['Fire','Water','Grass','Electric','Ice','Fighting','Poison','Ground','Flying','Psychic','Bug','Rock','Ghost','Dragon','Dark','Steel','Fairy','Normal'];
function dayKey(){return new Date().toISOString().slice(0,10)}function weekKey(){const x=new Date(),d=(x.getUTCDay()+6)%7;x.setUTCDate(x.getUTCDate()-d);return x.toISOString().slice(0,10)}
function pass(){core();const b=P.meta.battlePass=P.meta.battlePass||{};if(!b.season)b.season=1;if(!b.start)b.start=Date.now();if(!b.end)b.end=b.start+PASS_DAYS*86400000;if(Date.now()>=b.end){const carry=!!b.nextCoupon30;b.season++;b.start=b.end;b.end=b.start+PASS_DAYS*86400000;b.xp=0;b.premium=false;b.couponAvailable=carry;b.nextCoupon30=false;b.claimFree={};b.claimPremium={};b.daily=null;b.weekly=null;b.seasonal=null;b.counters={normal:0,survivor:0,world:0,captures:0,hunts:0,typeNormal:{},typeSurvivor:{},typeWorld:{}};b.dailyEarn={key:dayKey(),xp:0}}b.xp=clamp(Number(b.xp||0),0,PASS_TOTAL);b.claimFree=b.claimFree||{};b.claimPremium=b.claimPremium||{};b.counters=b.counters||{normal:0,survivor:0,world:0,captures:0,hunts:0,typeNormal:{},typeSurvivor:{},typeWorld:{}};b.counters.survivor=Number(b.counters.survivor||0);b.counters.typeNormal=b.counters.typeNormal||{};b.counters.typeSurvivor=b.counters.typeSurvivor||{};b.counters.typeWorld=b.counters.typeWorld||{};if(!b.dailyEarn||b.dailyEarn.key!==dayKey())b.dailyEarn={key:dayKey(),xp:0};ensureMissions(b);return b}
function passLvl(){return Math.min(PASS_MAX,Math.floor(pass().xp/PASS_XP_LEVEL))}function passInLevel(){const b=pass();return b.xp>=PASS_TOTAL?1000:b.xp%1000}
function addPassXP(x,organic=true){const b=pass();x=Math.max(0,Number(x||0));if(organic){const room=Math.max(0,PASS_DAILY_CAP-Number(b.dailyEarn.xp||0));x=Math.min(x,room);b.dailyEarn.xp+=x}const before=b.xp;b.xp=clamp(b.xp+x,0,PASS_TOTAL);save();return b.xp-before}
function counterValue(kind,type,bobj){const b=bobj||P.meta?.battlePass||{},c=b.counters||{};if(kind==='kills')return Number(c.survivor||0);if(kind==='hunts')return Number(c.hunts||0);if(kind==='eggs')return Number(P.meta?.eggHatches||0);if(kind==='type')return Number(c.typeSurvivor?.[type]||0);return 0}
function mission(id,label,kind,goal,xp,type){return{id,label,kind,goal,xp,type,start:counterValue(kind,type,P.meta?.battlePass),claimed:false}}
function ensureMissions(b){
 const dk=dayKey(),wk=weekKey();
 if(Number(b.missionVersion||0)!==44){b.daily=null;b.weekly=null;b.seasonal=null;b.missionVersion=44}
 if(!b.daily||b.daily.key!==dk){const ti=PASS_TYPES[Math.abs([...dk].reduce((a,c)=>a+c.charCodeAt(0),0))%PASS_TYPES.length];b.daily={key:dk,list:[mission('d_kill','Derrote 50 Pokémon no Survivor','kills',50,300),mission('d_kill2','Derrote 100 Pokémon no Survivor','kills',100,300),mission('d_type',`Derrote 30 Pokémon de ${ti} no Survivor`,'type',30,400,ti)]}}
 if(!b.weekly||b.weekly.key!==wk){const ti=PASS_TYPES[(new Date().getUTCMonth()+new Date().getUTCDate())%PASS_TYPES.length];b.weekly={key:wk,list:[mission('w_kill','Derrote 500 Pokémon no Survivor','kills',500,1600),mission('w_kill2','Derrote 1.000 Pokémon no Survivor','kills',1000,1400),mission('w_type',`Derrote 250 Pokémon de ${ti} no Survivor`,'type',250,1700,ti),mission('w_egg','Choque 8 Eggs','eggs',8,900)]}}
 if(!b.seasonal||b.seasonal.season!==b.season){const ti=PASS_TYPES[(b.season*3)%PASS_TYPES.length];b.seasonal={season:b.season,list:[mission('s_kill','Derrote 2.500 Pokémon no Survivor','kills',2500,5000),mission('s_egg','Choque 25 Eggs','eggs',25,4000),mission('s_kill2','Derrote 5.000 Pokémon no Survivor','kills',5000,5000),mission('s_type',`Derrote 1.000 Pokémon de ${ti} no Survivor`,'type',1000,4500,ti)]}}
}
function missionProg(m){return Math.max(0,counterValue(m.kind,m.type)-Number(m.start||0))}
W.psy20ClaimMission=function(scope,id){const b=pass(),box=b[scope],m=box?.list?.find(x=>x.id===id);if(!m||m.claimed||missionProg(m)<m.goal)return;const got=addPassXP(m.xp,false);if(got<=0)return toast('O Passe já está no nível máximo.');m.claimed=true;save();toast(`🎫 +${fmt(got)} XP do Passe`);W.openBattlePass(scope)};
function passTrackSurvivor(id){const b=pass();b.counters.survivor=Number(b.counters.survivor||0)+1;const gained=addPassXP(1,true);if(id){const t=passTypeOf(id);b.counters.typeSurvivor=b.counters.typeSurvivor||{};b.counters.typeSurvivor[t]=Number(b.counters.typeSurvivor[t]||0)+1}save();return gained}W.psyPassTrackSurvivor=passTrackSurvivor;
function passTrackWorld(id){return 0}
function passTypeOf(id){let raw='Normal';try{raw=String((typeof TYPE_BY_ID_ALL!=='undefined'?TYPE_BY_ID_ALL?.[id]:'')||W.TYPE_BY_ID_FULL?.[id]||'Normal').split('/')[0]}catch(e){}const map={Fogo:'Fire',Agua:'Water','Água':'Water',Planta:'Grass',Eletrico:'Electric','Elétrico':'Electric',Gelo:'Ice',Lutador:'Fighting',Venenoso:'Poison',Veneno:'Poison',Terra:'Ground',Voador:'Flying',Psiquico:'Psychic','Psíquico':'Psychic',Inseto:'Bug',Pedra:'Rock',Fantasma:'Ghost',Dragao:'Dragon','Dragão':'Dragon',Noturno:'Dark',Sombrio:'Dark',Aco:'Steel','Aço':'Steel',Metal:'Steel',Fada:'Fairy'};return map[raw]||raw}
const recordBase=W.psyRecordKill;W.psyRecordKill=function(n=1){return recordBase?.apply(this,arguments)};try{psyRecordKill=W.psyRecordKill}catch(e){}
const worldKillBase=W.handleWorldKill;W.handleWorldKill=function(t){return worldKillBase?.apply(this,arguments)};try{handleWorldKill=W.handleWorldKill}catch(e){}
const endBattleBase=W.endBattle;W.endBattle=function(won){
 const wild=W.battleData?.wild?{...battleData.wild}:null,hp=Number(W.battleData?.wildHp||0),gym=(typeof gymBattle!=='undefined'&&!!gymBattle),kill=!!(won&&wild&&hp<=0&&!gym&&!wild.psyduckDungeon&&!wild.eeveeDungeon&&!wild.psyduckDungeonV11&&!wild.psyduckDungeonV12);
 const r=endBattleBase?.apply(this,arguments);
 if(kill&&String(P.currentHunt||'').startsWith('psy19:')){const b=pass();b.counters.hunts=Number(b.counters.hunts||0)+1;save()}
 return r
};
const captureBase=W.tryCaptureBattle;W.tryCaptureBattle=function(){const b=pass(),before=Number(P.meta.captures||0);const r=captureBase?.apply(this,arguments);const after=Number(P.meta.captures||0),n=Math.max(0,after-before);if(n){b.counters.captures+=n;save()}return r};try{tryCaptureBattle=W.tryCaptureBattle}catch(e){}
/* Survivor Pass tracking is handled once in survKill(), the authoritative KO path. */
function reward(level,premium){return psy48Reward(level,premium)}
function firstStageSIds(){const out=[];const order={E:1,D:2,C:3,B:4,A:5,S:6,SS:7,SSS:8,UR:9,'UR+':10,'UR++':11};for(const id of Object.keys(W.ALL_POKE_NAMES||{}).map(Number)){if(!id)continue;try{if(W.getEvoStage?.(id)!==1)continue;const t=W.getTier?.(id,false,false,false)||'E';if((order[t]||99)<=6)out.push(id)}catch(e){}}return out.length?out:[1,4,7,25,54,133]}
function givePassShinyEgg(){core();P.eggV19=P.eggV19||{bag:[],inc:Array(8).fill(null),ko:0,log:[]};P.eggV19.bag=Array.isArray(P.eggV19.bag)?P.eggV19.bag:[];P.eggV19.bag.push({id:'bp_'+Date.now().toString(36),kind:'tier',value:'',tier:'S',source:'battlepass',instant:false,dur:3600000,start:0,ready:0,guaranteedShiny:true,firstStageOnly:true,maxTier:'S'});toast('🥚 Ovo Shiny do Passe enviado ao Egg Center!')}
const eggPreviewBase=W.psy19EggPreviewBag;W.psy19EggPreviewBag=function(id){core();const e=P.eggV19?.bag?.find(x=>x.id===id);if(!e?.guaranteedShiny)return eggPreviewBase?.apply(this,arguments);let s=$('psy20-pass-egg-preview');if(!s){s=D.createElement('div');s.id='psy20-pass-egg-preview';s.className='psy20-overlay';D.body.appendChild(s)}const ids=firstStageSIds().slice(0,24);s.style.display='flex';s.innerHTML=`<div class="psy20-panel" style="width:min(900px,96vw)"><button class="psy20-close" onclick="document.getElementById('psy20-pass-egg-preview').style.display='none'">×</button><h2 class="psy20-title">🥚✨ OVO SHINY DO PASSE</h2><div class="psy20-sub">Sempre nasce Shiny, somente primeira evolução e no máximo Rank S. A lista abaixo é uma amostra do pool elegível.</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(95px,1fr));gap:8px;margin-top:10px">${ids.map(pid=>`<div class="psy20-card" style="text-align:center"><img src="https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/shiny/${pid}.png" style="width:64px;height:64px;object-fit:contain;image-rendering:pixelated"><small>${esc(W.getPokeName?.(pid)||('Pokémon '+pid))}</small></div>`).join('')}</div></div>`};
const eggClaimBase=W.psy19EggClaim;W.psy19EggClaim=function(slot){core();const e=P.eggV19?.inc?.[slot];if(!e?.guaranteedShiny)return eggClaimBase?.apply(this,arguments);if(Date.now()<Number(e.ready||0))return toast('Este Egg ainda está incubando.');const ids=firstStageSIds(),id=ids[Math.floor(Math.random()*ids.length)];let rarity;try{rarity=W.rollRarity?.(W.getTier?.(id,true,false,false))}catch(x){}let p;try{p=W.createCapturedPoke?.(id,rarity,true,false,false)}catch(x){}if(!p)p={id,name:W.getPokeName?.(id)||`Pokémon ${id}`,level:1,shiny:true};if(P.team.length<6)P.team.push(p);else P.box.push(p);P.meta.eggHatches=Number(P.meta.eggHatches||0)+1;P.eggV19.inc[slot]=null;save();toast(`✨ O Egg do Passe chocou: Shiny ${p.name}!`,4000);W.renderEggCenter?.('incubator')};
W.psy20ClaimReward=function(level,track){const b=pass(),lv=passLvl(),premium=track==='premium';if(level>lv||level<1)return;if(premium&&!b.premium)return toast('Ative o Passe Premium para resgatar esta trilha.');const claims=premium?b.claimPremium:b.claimFree;if(claims[level])return;const r=reward(level,premium);if(r.kind==='gold')P.gold=Number(P.gold||0)+r.qty;else if(r.kind==='dia')P.diamonds=Number(P.diamonds||0)+r.qty;else if(r.kind==='item')P.inventory[r.key]=Number(P.inventory[r.key]||0)+r.qty;else if(r.kind==='pack')P.cardGame.packs[r.key]=Number(P.cardGame.packs[r.key]||0)+r.qty;else if(r.kind==='egg')psy48GivePassEgg(r);else if(r.kind==='shinyEgg')givePassShinyEgg();else if(r.kind==='coupon')b.nextCoupon30=true;claims[level]=1;save();W.openBattlePass()};
W.psy20BuyPassXP=function(q=1){const b=pass();q=clamp(Number(q)||1,1,100);if(P.psycoin<q)return toast(`Precisa ${q} PsyCoin.`);if(b.xp>=PASS_TOTAL)return toast('Passe já está no nível 100.');P.psycoin-=q;addPassXP(1500*q,false);save();toast(`🎫 +${fmt(1500*q)} XP do Passe`);W.openBattlePass()};
W.psy20ActivatePremium=function(){const b=pass();if(b.premium)return;const cost=b.couponAvailable?7:10;if(P.psycoin<cost)return toast(`Precisa ${cost} PsyCoin.`);P.psycoin-=cost;b.premium=true;if(b.couponAvailable)b.couponAvailable=false;save();toast('🌟 Passe Premium ativado!');W.openBattlePass()};
function timeLeft(ms){ms=Math.max(0,ms);const d=Math.floor(ms/86400000),h=Math.floor(ms%86400000/3600000),m=Math.floor(ms%3600000/60000);return`${d}d ${h}h ${m}m`}
function rewardCell(lvl,premium){const b=pass(),r=reward(lvl,premium),claimed=!!(premium?b.claimPremium[lvl]:b.claimFree[lvl]),ready=passLvl()>=lvl&&(!premium||b.premium);return`<div class="psy20-reward ${premium?'premium':''} ${claimed?'claimed':ready?'ready':''}"><div class="ri">${r.icon}</div><b>${esc(r.label)}</b><small>${esc(r.sub)}</small><button class="psy20-btn ${premium?'gold':'green'}" ${!ready||claimed?'disabled':''} onclick="psy20ClaimReward(${lvl},'${premium?'premium':'free'}')">${claimed?'RESGATADO':ready?'RESGATAR':'🔒'}</button></div>`}
function passLevels(){return Array.from({length:100},(_,i)=>i+1)}
function missionHtml(scope){const box=pass()[scope],list=box?.list||[];return list.map(m=>{const p=missionProg(m),done=p>=m.goal;return`<div class="psy20-mission"><div><b>${esc(m.label)}</b><div class="psy20-sub">${fmt(Math.min(p,m.goal))}/${fmt(m.goal)} • +${fmt(m.xp)} XP do Passe</div></div><button class="psy20-btn ${done&&!m.claimed?'green':''}" ${!done||m.claimed?'disabled':''} onclick="psy20ClaimMission('${scope}','${esc(m.id)}')">${m.claimed?'OK':done?'RESGATAR':'EM PROGRESSO'}</button></div>`}).join('')}
W.psy20PassTab=function(t){const h=$('psy20-pass-missions');if(h)h.innerHTML=missionHtml(t);D.querySelectorAll('.psy20-mtab button').forEach(b=>b.classList.toggle('purple',b.dataset.tab===t))};
W.openBattlePass=function(tab='daily'){core();const b=pass(),lv=passLvl(),levels=passLevels(),cost=b.couponAvailable?7:10;let s=$('psy20-pass-screen');if(!s){s=D.createElement('div');s.id='psy20-pass-screen';s.className='psy20-overlay';D.body.appendChild(s)}s.style.display='flex';s.innerHTML=`<div class="psy20-panel psy20-pass"><button class="psy20-close" onclick="document.getElementById('psy20-pass-screen').style.display='none'">×</button><div class="psy20-row"><div><h2 class="psy20-title" style="font-size:29px">PASSE DE TEMPORADA</h2><div style="color:#d946ef;font-weight:900">TEMPORADA ${b.season} • <span style="color:#38bdf8">PSYWORLD</span></div></div><div class="psy20-pill">⏱ TERMINA EM ${timeLeft(b.end-Date.now())}</div><div class="psy20-pill">💠 ${fmt(P.psycoin)} PsyCoin</div></div><div class="psy20-pass-head" style="margin-top:10px"><div class="psy20-pass-mascot free"><div><h2>PASSE<br>GRÁTIS</h2><div class="psy20-pill" style="margin-top:12px">NÍVEL ${lv}</div></div><img src="https://play.pokemonshowdown.com/sprites/ani/psyduck.gif"></div><div class="psy20-pass-benefit"><h3>BENEFÍCIOS DO PASSE PREMIUM</h3><ul><li>Recompensas Premium exclusivas.</li><li>100 níveis na mesma progressão do Passe Grátis.</li><li>No Nível 100: cupom de 30% no próximo Passe.</li><li>Recompensas aumentam de valor conforme você avança pelos 100 níveis.</li></ul></div><div class="psy20-pass-mascot prem"><img src="https://play.pokemonshowdown.com/sprites/ani-shiny/psyduck.gif"><div><h2>PASSE<br>PREMIUM</h2><button class="psy20-btn gold" style="margin-top:12px" ${b.premium?'disabled':''} onclick="psy20ActivatePremium()">${b.premium?'ATIVO':`ATIVAR • 💠 ${cost}`}</button></div></div></div><div class="psy20-pass-progress"><div class="lvl">NÍVEL<br>${lv}</div><div><div class="psy20-row"><b>XP DO PASSE</b><span>${fmt(passInLevel())} / 1.000</span></div><div class="psy20-passbar"><i style="width:${b.xp>=PASS_TOTAL?100:passInLevel()/10}%"></i></div></div><button class="psy20-btn" onclick="psy20BuyPassXP(1)">COMPRAR NÍVEL<br><small>💠 1 = 1.500 XP</small></button></div><div class="psy20-rewards"><div class="psy20-reward-head"><div class="psy20-track-label" style="background:#08213c">NÍVEL</div>${levels.map(x=>`<div>${x}</div>`).join('')}</div><div class="psy20-reward-row"><div class="psy20-reward psy20-track-label" style="background:#08213c"><b>GRÁTIS</b><img src="https://play.pokemonshowdown.com/sprites/ani/psyduck.gif" style="width:55px;height:55px;object-fit:contain"></div>${levels.map(x=>rewardCell(x,false)).join('')}</div><div class="psy20-reward-row"><div class="psy20-reward premium psy20-track-label" style="background:#241a05"><b>PREMIUM</b><img src="https://play.pokemonshowdown.com/sprites/ani-shiny/psyduck.gif" style="width:55px;height:55px;object-fit:contain"></div>${levels.map(x=>rewardCell(x,true)).join('')}</div></div><div class="psy20-pass-bottom"><div class="psy20-card"><h3 style="margin:0">MISSÕES DO PASSE</h3><div class="psy20-mtab"><button class="psy20-btn" data-tab="daily" onclick="psy20PassTab('daily')">DIÁRIAS</button><button class="psy20-btn" data-tab="weekly" onclick="psy20PassTab('weekly')">SEMANAIS</button><button class="psy20-btn" data-tab="seasonal" onclick="psy20PassTab('seasonal')">TEMPORADA</button></div><div id="psy20-pass-missions"></div></div><div class="psy20-card"><h3 style="margin:0">COMO GANHAR XP DO PASSE</h3><ul class="psy20-sub" style="font-size:11px;line-height:1.75"><li>1 Pokémon derrotado no <b>Survivor</b> = <b>1 XP</b> do Passe.</li><li>Wild, Fast Encounter e WORLD não concedem XP direto por derrota.</li><li>Complete missões diárias, semanais e sazonais.</li><li>1.000 XP = 1 nível.</li></ul><div class="psy20-row"><span class="psy20-pill">Survivor: 1 KO = 1 XP</span><span class="psy20-pill">Missões dão XP extra</span></div></div><div class="psy20-card"><h3 style="margin:0">COMPRAR NÍVEIS</h3><div style="font-size:20px;font-weight:1000;margin:14px 0">1 💠 = 1.500 XP</div><button class="psy20-btn green" style="width:100%" onclick="psy20BuyPassXP(1)">COMPRAR 💠 1</button></div><div class="psy20-card"><h3 style="margin:0">SUA JORNADA</h3><div style="font-size:28px;color:#facc15;font-weight:1000">Nível ${lv}</div><div class="psy20-sub">XP total: ${fmt(b.xp)} / ${fmt(PASS_TOTAL)}</div><div class="psy20-sub">XP orgânico hoje: ${fmt(b.dailyEarn.xp)} / ${fmt(PASS_DAILY_CAP)}</div></div></div><div class="psy20-note">ℹ O XP orgânico do Passe possui limite diário de 7.000 XP. XP comprado com PsyCoin não entra nesse limite.</div></div>`;W.psy20PassTab(tab)};

