const PACKS20={normal:{n:'Pack Normal',qty:5,c:'#64748b',cur:'gold',p:90000,t:'E–B',a:25,b:7},rare:{n:'Pack Raro',qty:7,c:'#3b82f6',cur:'gold',p:260000,t:'D–S',a:94,b:133},epic:{n:'Pack Épico',qty:10,c:'#a855f7',cur:'gold',p:650000,t:'C–S',a:6,b:130},s:{n:'Pack S',qty:10,c:'#ef4444',cur:'gold',p:1250000,t:'B–S',a:149,b:248},ss:{n:'Pack SS',qty:10,c:'#facc15',global:true,t:'S–SS',a:150,b:249},sss:{n:'Pack SSS',qty:10,c:'#22d3ee',cur:'dia',p:80,t:'SSS+',a:384,b:483},ur:{n:'Pack UR',qty:10,c:'#f472b6',cur:'dia',p:150,t:'UR+',a:493,b:716},urp:{n:'Pack UR+',qty:10,c:'#e879f9',cur:'dia',p:260,t:'UR+',a:800,b:888},urpp:{n:'Pack UR++',qty:10,c:'#ffffff',cur:'dia',p:450,t:'UR++',a:890,b:1024}};
function allIds(){
  let src={};
  try{src=(typeof ALL_POKE_NAMES!=='undefined'&&ALL_POKE_NAMES)?ALL_POKE_NAMES:(W.ALL_POKE_NAMES||{})}catch(e){src=W.ALL_POKE_NAMES||{}}
  let ids=Object.keys(src||{}).map(Number).filter(x=>Number.isFinite(x)&&x>0&&x<=1025);
  if(!ids.length){
    try{ids=Object.keys(typeof TYPE_BY_ID_ALL!=='undefined'?(TYPE_BY_ID_ALL||{}):(W.TYPE_BY_ID_ALL||W.TYPE_BY_ID_FULL||{})).map(Number).filter(x=>Number.isFinite(x)&&x>0&&x<=1025)}catch(e){}
  }
  if(!ids.length)ids=Array.from({length:1025},(_,i)=>i+1);
  return ids;
}function legs(){const a=[];try{for(const id of allIds())if(typeof LEGENDARY_IDS!=='undefined'&&LEGENDARY_IDS.has(id))a.push(id)}catch(e){}return a.length?a:[144,145,146,150,249,250,384,483,484,716,717,800,888,889,890]}
function megas(){try{if(typeof OFFICIAL_MEGA_SET!=='undefined')return [...OFFICIAL_MEGA_SET].map(Number).filter(Boolean)}catch(e){}return[3,6,9,15,18,65,80,94,115,127,130,142,150,181,208,212,214,229,248,254,257,260,282,302,303,306,308,310,319,323,334,354,359,362,373,376,380,381,384,428,445,448,460,475,531,719]}
function stickerKey(e){return`${e.variant||'normal'}:${e.id}${e.sub?':'+e.sub:''}`}
function addSticker(e){core();const k=stickerKey(e),old=P.cardGame.stickers[k]||{copies:0};P.cardGame.stickers[k]={...e,copies:Number(old.copies||0)+1};return P.cardGame.stickers[k]}
function rollSticker20(key){const r=Math.random(),ids=allIds(),leg=legs(),meg=megas();if(key==='normal')return{id:ids[Math.floor(Math.random()*ids.length)],variant:r<.10?'shiny':'normal'};if(key==='rare')return r<.08?{id:meg[Math.floor(Math.random()*meg.length)],variant:'mega'}:r<.22?{id:ids[Math.floor(Math.random()*ids.length)],variant:'shiny'}:{id:ids[Math.floor(Math.random()*ids.length)],variant:'normal'};if(key==='epic')return r<.08?{id:leg[Math.floor(Math.random()*leg.length)],variant:'legendary'}:r<.18?{id:meg[Math.floor(Math.random()*meg.length)],variant:'mega_shiny'}:r<.36?{id:meg[Math.floor(Math.random()*meg.length)],variant:'mega'}:{id:ids[Math.floor(Math.random()*ids.length)],variant:'shiny'};if(key==='s')return r<.18?{id:leg[Math.floor(Math.random()*leg.length)],variant:'legendary'}:r<.38?{id:meg[Math.floor(Math.random()*meg.length)],variant:'mega_shiny'}:{id:ids[Math.floor(Math.random()*ids.length)],variant:'shiny'};if(key==='ss')return r<.35?{id:leg[Math.floor(Math.random()*leg.length)],variant:'legendary'}:{id:meg[Math.floor(Math.random()*meg.length)],variant:'mega_shiny'};if(key==='sss')return r<.25?{id:54,variant:'psyduck',sub:'shiny',label:'Psyduck Shiny'}:r<.60?{id:leg[Math.floor(Math.random()*leg.length)],variant:'legendary'}:{id:meg[Math.floor(Math.random()*meg.length)],variant:'mega_shiny'};if(key==='ur')return r<.18?{id:54,variant:'psyduck',sub:'mega',label:'Psyduck Mega'}:r<.65?{id:leg[Math.floor(Math.random()*leg.length)],variant:'legendary'}:{id:meg[Math.floor(Math.random()*meg.length)],variant:'mega_shiny'};if(key==='urp')return r<.22?{id:54,variant:'psyduck',sub:'mega_shiny',label:'Psyduck Mega Shiny'}:r<.70?{id:leg[Math.floor(Math.random()*leg.length)],variant:'legendary'}:{id:meg[Math.floor(Math.random()*meg.length)],variant:'mega_shiny'};return r<.25?{id:54,variant:'psyduck',sub:'squizo',label:'Psyduck Squizo'}:r<.65?{id:leg[Math.floor(Math.random()*leg.length)],variant:'legendary'}:{id:meg[Math.floor(Math.random()*meg.length)],variant:'mega_shiny'}}
W.psyBuyPack=function(k){core();const x=PACKS20[k];if(!x||x.global)return toast('Este Pack é obtido por drop/conteúdo especial.');if(x.cur==='gold'){if(P.gold<x.p)return toast(`Precisa ${fmt(x.p)} Gold.`);P.gold-=x.p}else{if(Number(P.diamonds||0)<x.p)return toast(`Precisa ${x.p} Diamantes.`);P.diamonds-=x.p}P.cardGame.packs[k]=Number(P.cardGame.packs[k]||0)+1;save();W.renderCardTab?.('gacha')};
W.cgOpenPack=function(k){
  core();psy55FusionEnsure();
  const x=PACKS20[k],owned=Number(P.cardGame.packs[k]||0);
  if(!x||owned<=0)return toast('Você não possui este Pack.');
  const pulls=[];
  for(let i=0;i<x.qty;i++){
    let raw=null;
    for(let tries=0;tries<5&&!raw;tries++)raw=psy22Entry(rollSticker20(k));
    if(!raw)continue;
    raw.stickerRank=k;
    const sk=stickerKey(raw),before=Number(P.cardGame.stickers[sk]?.copies||0),stored=addSticker(raw),e={...raw,copies:Number(stored.copies||1),wasDuplicate:before>0};
    if(before>0)psy55RecordDuplicate(sk,k);
    pulls.push(e);
  }
  if(!pulls.length){
    console.error('Pack sem resultados válidos',k,{ids:allIds().length,legendarios:legs().length,megas:megas().length});
    return toast('Falha ao gerar as figurinhas. O Pack não foi consumido.');
  }
  P.cardGame.packs[k]=Math.max(0,owned-1);
  P.cardGame.lastPack=pulls;
  P.cardGame.stickerHistory.unshift({when:Date.now(),pack:k,name:x.n,items:pulls.map(v=>({...v}))});
  P.cardGame.stickerHistory=P.cardGame.stickerHistory.slice(0,20);
  save();
  psy22OpenResult(pulls,x.n);
  W.renderCardTab?.('gacha');
};
function packSprite(id){try{return W.getRealSprite?.({id})||`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png`}catch(e){return`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png`}}
function pack20(k,x){const own=Number(P.cardGame.packs[k]||0),price=x.global?'DROP GLOBAL':x.cur==='gold'?`${fmt(x.p)} Gold`:`${x.p} Diamantes`;return`<div class="psy20-pack" style="--pc:${x.c}"><div class="psy20-pack-art"><img class="a" src="${packSprite(x.a)}"><div class="psy20-foil">${esc(k.toUpperCase())}</div><img class="b" src="${packSprite(x.b)}"></div><h3 style="margin:0">${esc(x.n)}</h3><div class="psy20-sub">${x.qty} figurinhas • faixa ${esc(x.t)}</div><div class="psy20-row" style="margin:8px 0"><b>${own}x</b><span style="color:#facc15;font-weight:900">${price}</span></div><button class="psy20-btn green" style="width:100%" ${own<=0?'disabled':''} onclick="window.cgOpenPack('${k}')">ABRIR</button>${x.global?'':`<button class="psy20-btn" style="width:100%;margin-top:6px" onclick="window.psyBuyPack('${k}')">COMPRAR</button>`}</div>`}
const cardTabBase=W.renderCardTab;W.renderCardTab=function(tab){if(tab!=='gacha')return cardTabBase?.apply(this,arguments);core();const host=$('cg-content');if(!host)return;host.innerHTML=`<div class="psy15-gacha-head"><div class="psy15-panel"><h2 style="margin:0">✨ GACHA DE FIGURINHAS</h2><div style="color:#a7c2e9;font-size:12px;margin-top:5px">Packs por faixa de raridade, com arte própria. Nenhum botão AFK nesta tela.</div></div><div class="psy15-panel"><b>💠 PsyCoin</b><div style="font-size:12px;color:#d8b4fe;margin-top:5px">Saldo: ${fmt(P.psycoin)}</div><button onclick="window.openPsyCoinTutorial&&window.openPsyCoinTutorial()">COMO CONSEGUIR?</button></div></div><div class="psy20-packgrid">${Object.entries(PACKS20).map(([k,x])=>pack20(k,x)).join('')}</div>`};

/* ============================================================
   QUESTS — restored elemental hunting contracts
   ============================================================ */
const QUEST_LOOT20={
 Normal:['Rubber Ball','Giant Piece Of Fur'],Fire:['Essence Of Fire','Fire Tail'],Water:['Water Gem','Water Pendant'],Grass:['Seed','Great Petal'],Electric:['Screw','Electric Rat Tail'],Ice:['Snowball','Ice Orb'],Fighting:['Band Aid','Belt Of Champion'],Poison:['Bottle Of Poison','Bug Venom'],Ground:['Earth Ball','Piece Of Diglett'],Flying:['Straw','Giant Beak'],Psychic:['Enchanted Gem','Psychic Spoon'],Bug:['Bug Gosme','Bug Antenna'],Rock:['Small Stone','Strange Rock'],Ghost:['Ghost Essence','Bat Wing'],Dragon:['Dragon Scale','Dragon Tooth'],Dark:['Dark Gem','Dark Ear'],Steel:['Piece Of Steel','Metal Hull'],Fairy:['Rubber Ball','Cute Ball']
};
const QUEST_TYPES20=['Normal','Fire','Water','Grass','Electric','Ice','Fighting','Poison','Ground','Flying','Psychic','Bug','Rock','Ghost','Dragon','Dark','Steel','Fairy'];
const QUEST_PT20={Normal:'Normal',Fire:'Fogo',Water:'Água',Grass:'Planta',Electric:'Elétrico',Ice:'Gelo',Fighting:'Lutador',Poison:'Veneno',Ground:'Terra',Flying:'Voador',Psychic:'Psíquico',Bug:'Inseto',Rock:'Pedra',Ghost:'Fantasma',Dragon:'Dragão',Dark:'Sombrio',Steel:'Metal',Fairy:'Fada'};
function questType20(id){let raw='Normal';try{raw=String(TYPE_BY_ID_ALL?.[id]||TYPE_BY_ID_FULL?.[id]||'Normal').split('/')[0].trim()}catch(e){}const map={Fogo:'Fire',Agua:'Water','Água':'Water',Planta:'Grass',Eletrico:'Electric','Elétrico':'Electric',Gelo:'Ice',Lutador:'Fighting',Veneno:'Poison',Venenoso:'Poison',Terra:'Ground',Voador:'Flying',Psiquico:'Psychic','Psíquico':'Psychic',Inseto:'Bug',Pedra:'Rock',Fantasma:'Ghost',Dragao:'Dragon','Dragão':'Dragon',Noturno:'Dark',Sombrio:'Dark',Aco:'Steel','Aço':'Steel',Metal:'Steel',Fada:'Fairy'};raw=map[raw]||raw;return QUEST_LOOT20[raw]?raw:'Normal'}
function questDefs20(){return QUEST_TYPES20.map(t=>{const e=PSY_ELEMENT_DATA[t]||PSY_ELEMENT_DATA.Normal,pair=QUEST_LOOT20[t];return{id:'q20_'+t,n:`Contrato ${QUEST_PT20[t]}`,type:t,need:[[pair[0],18],[pair[1],3]],gold:42000,ball:e.ball,color:e.color||'#38bdf8',ico:e.ico||'📜'}})}
function questReady20(q){return q.need.every(([n,a])=>Number(P.inventory?.[n]||0)>=a)}
W.psyQuestDrop=function(id){core();const t=questType20(id),pair=QUEST_LOOT20[t]||QUEST_LOOT20.Normal,boost=Math.min(2.2,1+Math.max(0,Number(W.getTotalBuff?.('drop')||0))/100),got=[];if(Math.random()<.16*boost){P.inventory[pair[0]]=Number(P.inventory[pair[0]]||0)+1;got.push(pair[0])}if(Math.random()<.026*boost){P.inventory[pair[1]]=Number(P.inventory[pair[1]]||0)+1;got.push(pair[1])}if(got.length){save();toast(`📜 Loot de Quest: ${got.join(' + ')}`,1700)}return got};
try{psyQuestDrop=W.psyQuestDrop}catch(e){}
W.psy20ClaimQuest=function(id){core();P.meta.lootQuestClaims=P.meta.lootQuestClaims||{};const q=questDefs20().find(x=>x.id===id);if(!q||!questReady20(q))return toast('Ainda faltam materiais para este contrato.');for(const [n,a] of q.need){P.inventory[n]=Number(P.inventory[n]||0)-a;if(P.inventory[n]<=0)delete P.inventory[n]}P.gold=Number(P.gold||0)+q.gold;P.inventory[q.ball]=Number(P.inventory[q.ball]||0)+1;P.meta.lootQuestClaims[id]=Number(P.meta.lootQuestClaims[id]||0)+1;save();toast(`📜 ${q.n}: +${fmt(q.gold)} Gold + 1 ${q.ball}`,2800);W.openQuestsV11()};
W.openQuestsV11=function(){core();P.meta.lootQuestClaims=P.meta.lootQuestClaims||{};let s=$('psy20-quests');if(!s){s=D.createElement('div');s.id='psy20-quests';s.className='psy20-overlay';D.body.appendChild(s)}s.style.display='flex';s.innerHTML=`<div class="psy20-panel"><button class="psy20-close" onclick="document.getElementById('psy20-quests').style.display='none'">×</button><h2 class="psy20-title">📜 QUESTS — CONTRATOS DE CAÇADA</h2><div class="psy20-sub">Loot de Quest é separado das Essências de Craft. Pokémon de cada elemento podem derrubar um material comum e um raro. Troque 18 comuns + 3 raros por Gold e 1 Ball elemental. Os contratos são repetíveis.</div><div class="psy20-achgrid" style="margin-top:12px">${questDefs20().map(q=>{const ready=questReady20(q),claims=Number(P.meta.lootQuestClaims[q.id]||0);return`<div class="psy20-ach ${ready?'ready':''}" style="border-color:${ready?'#22c55e':q.color}"><h3 style="color:${q.color}">${q.ico} ${esc(q.n)}</h3><small>Concluídos: ${fmt(claims)}</small>${q.need.map(([n,a])=>`<div style="display:flex;align-items:center;gap:7px;margin-top:7px">${W.psyV11ItemIcon?.(n)||'◇'}<span>${esc(n)}: <b>${fmt(P.inventory[n]||0)}/${a}</b></span></div>`).join('')}<div style="color:#facc15;margin-top:8px">+${fmt(q.gold)} Gold • +1 ${esc(q.ball)}</div><button class="psy20-btn ${ready?'green':''}" style="width:100%;margin-top:8px" ${ready?'':'disabled'} onclick="window.psy20ClaimQuest('${q.id}')">${ready?'TROCAR AGORA':'FALTAM ITENS'}</button></div>`}).join('')}</div></div>`};
try{openQuestsV11=W.openQuestsV11;psy20ClaimQuest=W.psy20ClaimQuest}catch(e){}

/* ============================================================
   Achievements + repeatables + visible wheel result
   ============================================================ */
const ACH20=[{id:'kill50',n:'Primeiros Passos',d:'Derrote 50 Pokémon',kind:'kills',g:50,gold:50000,dia:5},{id:'kill300',n:'Caçador Persistente',d:'Derrote 300 Pokémon',kind:'kills',g:300,gold:180000,dia:12},{id:'cap25',n:'Colecionador de Campo',d:'Capture 25 Pokémon',kind:'captures',g:25,gold:120000,dia:8},{id:'dex100',n:'Professor de Campo',d:'Registre 100 espécies',kind:'dex',g:100,gold:350000,dia:15},{id:'gym8',n:'Campeão de Kanto',d:'Derrote 8 líderes',kind:'gyms',g:8,gold:400000,dia:20},{id:'egg5',n:'Criador de Eggs',d:'Choque 5 Eggs',kind:'eggs',g:5,gold:200000,dia:10},{id:'album100',n:'Álbum em Crescimento',d:'Obtenha 100 figurinhas',kind:'album',g:100,gold:250000,dia:12},{id:'surv10',n:'Sobrevivente',d:'Alcance a Fase 10 do Survivor',kind:'surv',g:10,gold:300000,dia:15},{id:'surv50',n:'Psyduck Veterano',d:'Alcance a Fase 50 do Survivor',kind:'surv',g:50,gold:1200000,dia:50},{id:'tlv25',n:'Treinador Promissor',d:'Chegue ao Trainer Lv.25',kind:'trainer',g:25,gold:300000,dia:15}];
function achVal(a){core();if(a.kind==='kills')return Number(P.meta.kills||0);if(a.kind==='captures')return Number(P.meta.captures||0);if(a.kind==='dex')return Object.keys(P.meta.caughtDex||{}).length;if(a.kind==='gyms')return Number(P.gymProgress?.length||0);if(a.kind==='eggs')return Number(P.meta.eggHatches||0);if(a.kind==='album')return Object.keys(P.cardGame.stickers||{}).length;if(a.kind==='surv'){try{return Number(v12PsyTreeEnsure()?.survivorBest||0)}catch(e){return 0}}if(a.kind==='trainer')return Number(P.trainerLevel||1);return 0}
W.psy20ClaimAch=function(id){core();P.meta.ach20=P.meta.ach20||{};const a=ACH20.find(x=>x.id===id);if(!a||P.meta.ach20[id]||achVal(a)<a.g)return;P.meta.ach20[id]=1;P.gold+=a.gold;P.diamonds=Number(P.diamonds||0)+a.dia;save();toast(`🏆 ${a.n}: recompensa resgatada!`);W.openAchievements()};
function repeatDefs(){let type='Normal';try{const types=Array.isArray(W.PSY_TYPE_NAMES)?W.PSY_TYPE_NAMES:['Normal','Fogo','Agua','Eletrico','Planta','Gelo','Lutador','Veneno','Terra','Voador','Psiquico','Inseto','Pedra','Fantasma','Dragao','Noturno','Metal','Fada'];const i=(new Date().getUTCDate()+new Date().getUTCMonth())%types.length;type=types[i]}catch(e){}return[{id:'rk50',n:'Caçada Sem Fim',d:'Derrote 50 Pokémon',kind:'kills',goal:50,gold:45000,dia:1},{id:'rc20',n:'Capturador Ativo',d:'Capture 20 Pokémon',kind:'captures',goal:20,gold:80000,dia:1},{id:'re5',n:'Incubador',d:'Choque 5 Eggs',kind:'eggs',goal:5,gold:70000,dia:1},{id:'rt',n:`Caçada Elemental — ${type}`,d:`Derrote 50 Pokémon de ${type}`,kind:'type',type,goal:50,gold:90000,dia:2}]}
function repeatVal(r){if(r.kind==='type'){try{return Number(W.psyV10RewardsEnsure?.().typeKills?.[r.type]||0)}catch(e){return 0}}return achVal(r)}
W.psy20ClaimRepeat=function(id){core();P.meta.repeat20=P.meta.repeat20||{};const r=repeatDefs().find(x=>x.id===id);if(!r)return toast('Missão repetível inválida.');const done=Math.floor(repeatVal(r)/r.goal),claimed=Number(P.meta.repeat20[id]||0),avail=Math.max(0,done-claimed);if(avail<=0)return toast('Ainda não há ciclo disponível para resgatar.');const g=Number(r.gold||0)*avail,d=Number(r.dia||0)*avail;P.meta.repeat20[id]=claimed+avail;P.gold=Number(P.gold||0)+g;P.diamonds=Number(P.diamonds||0)+d;save();toast(`♻ ${r.n} x${avail}: +${fmt(g)} Gold${d?' + '+fmt(d)+' Diamantes':''}`,3200);W.openAchievements()};try{psy20ClaimRepeat=W.psy20ClaimRepeat}catch(e){}
const WHEEL20=[
{l:'50.000 Gold',short:'50K GOLD',i:'🪙',f:()=>{P.gold=Number(P.gold||0)+50000;return true}},
{l:'100.000 Gold',short:'100K GOLD',i:'🪙',f:()=>{P.gold=Number(P.gold||0)+100000;return true}},
{l:'2 Diamantes',short:'2 DIAM.',i:'💎',f:()=>{P.diamonds=Number(P.diamonds||0)+2;return true}},
{l:'5 Diamantes',short:'5 DIAM.',i:'💎',f:()=>{P.diamonds=Number(P.diamonds||0)+5;return true}},
{l:'ATK +15% • 20 min',short:'ATK +15%',i:'⚔️',f:()=>W.psyV10AddTempBuff('dmg',15,20,'ATK +15%')},
{l:'XP +25% • 20 min',short:'XP +25%',i:'⭐',f:()=>W.psyV10AddTempBuff('xp',25,20,'XP +25%')},
{l:'Captura +15% • 20 min',short:'CAP +15%',i:'🎯',f:()=>W.psyV10AddTempBuff('cap',15,20,'Captura +15%')},
{l:'Gold +25% • 20 min',short:'GOLD +25%',i:'💰',f:()=>W.psyV10AddTempBuff('gold',25,20,'Gold +25%')}
];
function wheelMeta(){core();try{return W.psyV10RewardsEnsure?.()||P.meta}catch(e){return P.meta}}
W.v12SpinWheel=function(){
 const m=wheelMeta();
 if(Number(m.rouletteSpins||0)<=0)return toast('Você ainda não possui giro disponível.');
 if(W.__psy20WheelBusy)return;
 const wheel=$('psy20-wheel');
 if(!wheel)return toast('A Roleta ainda não terminou de carregar.');
 W.__psy20WheelBusy=true;
 m.rouletteSpins--;
 const spinsEl=$('psy20-wheel-spins');if(spinsEl)spinsEl.textContent=String(m.rouletteSpins||0);
 const btn=wheel.closest('.psy20-card')?.querySelector('button[onclick*="v12SpinWheel"]');if(btn){btn.disabled=true;btn.textContent='GIRANDO...'}
 const idx=Math.floor(Math.random()*WHEEL20.length);
 const sector=45,targetOffset=(360-(idx*sector+sector/2))%360;
 const start=Number(W.__psy20WheelRotation||0);
 const baseTurns=5+Math.floor(Math.random()*2);
 const target=start+(baseTurns*360)+((targetOffset-(start%360)+360)%360);
 W.__psy20WheelRotation=target;
 wheel.style.transition='none';
 wheel.style.transform=`rotate(${start}deg)`;
 void wheel.offsetWidth;
 let finished=false;
 const finish=()=>{
   if(finished)return;finished=true;
   wheel.style.transform=`rotate(${target}deg)`;
   const prize=WHEEL20[idx],ok=prize.f();
   if(ok===false){m.rouletteSpins++;W.__psy20WheelBusy=false;save();return toast('O prêmio não pôde ser aplicado. O giro foi devolvido.')}
   P.meta.psy20WheelLast={label:prize.l,icon:prize.i,time:Date.now()};
   save();try{updateHUD?.()}catch(e){}try{psy22BuffStrip?.()}catch(e){}
   W.__psy20WheelBusy=false;
   const r=$('psy20-wheel-result');if(r){r.style.display='flex';r.innerHTML=`<div class="psy20-panel" style="width:min(440px,92vw);text-align:center"><button class="psy20-close" onclick="document.getElementById('psy20-wheel-result').style.display='none';window.openAchievements()">×</button><div style="font-size:56px">${prize.i}</div><h2 class="psy20-title">VOCÊ GANHOU</h2><div style="font-size:24px;color:#facc15;font-weight:1000;margin:10px">${esc(prize.l)}</div><button class="psy20-btn green" onclick="document.getElementById('psy20-wheel-result').style.display='none';window.openAchievements()">OK</button></div>`}
 };
 try{
   if(typeof wheel.animate==='function'){
     const anim=wheel.animate([{transform:`rotate(${start}deg)`},{transform:`rotate(${target}deg)`}],{duration:3400,easing:'cubic-bezier(.08,.68,.08,1)',fill:'forwards'});
     anim.onfinish=finish;anim.oncancel=finish;
   }else{
     requestAnimationFrame(()=>requestAnimationFrame(()=>{wheel.style.transition='transform 3.4s cubic-bezier(.08,.68,.08,1)';wheel.style.transform=`rotate(${target}deg)`;setTimeout(finish,3450)}));
   }
 }catch(e){wheel.style.transition='transform 3.4s cubic-bezier(.08,.68,.08,1)';requestAnimationFrame(()=>{wheel.style.transform=`rotate(${target}deg)`});setTimeout(finish,3450)}
};try{v12SpinWheel=W.v12SpinWheel}catch(e){}
W.openAchievements=function(){core();const m=wheelMeta();let s=$('psy20-ach-screen');if(!s){s=D.createElement('div');s.id='psy20-ach-screen';s.className='psy20-overlay';D.body.appendChild(s)}if(!$('psy20-wheel-result')){const r=D.createElement('div');r.id='psy20-wheel-result';r.className='psy20-overlay';r.style.display='none';D.body.appendChild(r)}P.meta.ach20=P.meta.ach20||{};P.meta.repeat20=P.meta.repeat20||{};s.style.display='flex';s.innerHTML=`<div class="psy20-panel"><button class="psy20-close" onclick="document.getElementById('psy20-ach-screen').style.display='none'">×</button><h2 class="psy20-title">🏆 CONQUISTAS & ROLETA</h2><div class="psy20-ach-layout" style="margin-top:10px"><div class="psy20-card"><h3 style="text-align:center;margin:0">🎡 ROLETA DA JORNADA</h3><div class="psy20-wheel-wrap"><div class="psy20-wheel-pointer"></div><div id="psy20-wheel" class="psy20-wheel">${WHEEL20.map((p,i)=>`<span class="psy21-wheel-label" style="transform:rotate(${i*45+22.5}deg) translateY(-82px) rotate(${-i*45-22.5}deg)">${esc(p.short||p.l)}</span>`).join('')}<span class="psy21-wheel-center">PRÊMIOS</span></div></div><div style="text-align:center">Giros disponíveis: <b id="psy20-wheel-spins">${fmt(m.rouletteSpins||0)}</b> • próximo em <b id="psy20-wheel-time">${typeof psyFmtTime==='function'?psyFmtTime(Math.max(0,1800-Number(m.rouletteProgress||0))):Math.ceil(Math.max(0,1800-Number(m.rouletteProgress||0))/60)+'m'}</b></div><button class="psy20-btn gold" style="width:100%;margin-top:8px" ${Number(m.rouletteSpins||0)<=0?'disabled':''} onclick="window.v12SpinWheel()">GIRAR</button>${P.meta.psy20WheelLast?`<div class="psy20-pill" style="margin-top:8px;width:100%;justify-content:center">Último prêmio: ${P.meta.psy20WheelLast.icon} ${esc(P.meta.psy20WheelLast.label)}</div>`:''}</div><div><div class="psy20-achgrid">${ACH20.map(a=>{const v=achVal(a),done=v>=a.g,claimed=!!P.meta.ach20[a.id],pct=Math.min(100,v/a.g*100);return`<div class="psy20-ach ${done&&!claimed?'ready':''}"><h3>${esc(a.n)}</h3><small>${esc(a.d)}</small><div class="psy20-achbar"><i style="width:${pct}%"></i></div><div>${fmt(Math.min(v,a.g))}/${fmt(a.g)}</div><div style="color:#facc15">${fmt(a.gold)} Gold • 💎 ${a.dia}</div><button class="psy20-btn ${done&&!claimed?'green':''}" ${!done||claimed?'disabled':''} onclick="window.psy20ClaimAch('${a.id}')">${claimed?'RESGATADO':done?'RESGATAR':'EM PROGRESSO'}</button></div>`}).join('')}</div><div class="psy20-repeat"><h3>♻ MISSÕES REPETÍVEIS</h3><div class="psy20-achgrid">${repeatDefs().map(r=>{const v=repeatVal(r),done=Math.floor(v/r.goal),claimed=Number(P.meta.repeat20[r.id]||0),avail=done-claimed,rem=v%r.goal,shown=avail>0?r.goal:rem;return`<div class="psy20-ach ${avail>0?'ready':''}"><h3>${esc(r.n)}</h3><small>${esc(r.d)}</small><div class="psy20-achbar"><i style="width:${Math.min(100,shown/r.goal*100)}%"></i></div><div>${fmt(shown)}/${fmt(r.goal)} • ciclos ${done}</div><div style="color:#facc15">${fmt(r.gold)} Gold • 💎 ${r.dia}</div><button class="psy20-btn ${avail>0?'green':''}" ${avail<=0?'disabled':''} onclick="window.psy20ClaimRepeat('${r.id}')">${avail>0?'RESGATAR':'CONTINUE'}</button></div>`}).join('')}</div></div></div></div></div>`};

