function psy48Reward(level,premium){level=String(Number(level));return (premium?PSY48_PREMIUM_REWARDS:PSY48_FREE_REWARDS)[level]||{icon:'•',label:'Recompensa',sub:'',kind:'none'}}
function psy48GivePassEgg(r){core();P.eggV19=P.eggV19||{bag:[],inc:Array(8).fill(null),ko:0,log:[]};P.eggV19.bag=Array.isArray(P.eggV19.bag)?P.eggV19.bag:[];const kind=r.eggKind||'random',value=r.eggValue||'',tier=r.eggTier||'E',e={id:'bp48_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),kind,value,tier,source:kind==='random'?'shop':'battlepass',passSource:'battlepass',instant:false,dur:300000,start:0,ready:0};P.eggV19.bag.push(e);P.eggV19.log=Array.isArray(P.eggV19.log)?P.eggV19.log:[];P.eggV19.log.unshift({t:Date.now(),m:`${r.label} recebido pelo Passe`});P.eggV19.log=P.eggV19.log.slice(0,20);toast(`🥚 ${r.label} enviado ao Egg Center!`)}
function psy48PassAudit(){const out={free:{},premium:{}};for(const [name,map] of [['free',PSY48_FREE_REWARDS],['premium',PSY48_PREMIUM_REWARDS]]){const a=out[name];a.gold=0;a.boost=0;a.shiny=0;a.mega=0;a.eggs=0;a.packs={rare:0,epic:0,s:0,ss:0,sss:0,ur:0};a.balls={};for(const r of Object.values(map)){if(r.kind==='gold')a.gold+=r.qty||0;if(r.kind==='item'&&r.key==='Boost Stone')a.boost+=r.qty||0;if(r.kind==='item'&&r.key==='Shiny Stone')a.shiny+=r.qty||0;if(r.kind==='item'&&r.key==='Fragmento Mega Stone')a.mega+=r.qty||0;if(r.kind==='item'&&/ Ball$/.test(r.key||''))a.balls[r.key]=(a.balls[r.key]||0)+(r.qty||0);if(r.kind==='pack')a.packs[r.key]=(a.packs[r.key]||0)+(r.qty||0);if(r.kind==='egg'||r.kind==='shinyEgg')a.eggs++;}}return out}
W.psy48PassAudit=psy48PassAudit;

