/* ---------- Psyduck tabs restored + redesigned Survivor tree ---------- */
function psy22TreeState(){try{return v12PsyTreeEnsure()}catch(e){P.psyduck=P.psyduck||{};P.psyduck.survSkills=P.psyduck.survSkills||{};P.psyduck.trialsDone=P.psyduck.trialsDone||{};P.psyduck.survivorBest=Number(P.psyduck.survivorBest||0);return P.psyduck}}
W.v12RenderPsyTree=function(c){if(!c)return;const ps=psy22TreeState(),defs=typeof V12_PSY_TREE!=='undefined'?V12_PSY_TREE:{};const normal='https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/54.png',shiny='https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/shiny/54.png';c.innerHTML=`<div class="psy20-card"><h3 style="margin:0;color:#67e8f9">🌌 CONSTELAÇÃO PSYDUCK — ÁRVORE SURVIVOR</h3><div class="psy20-sub">Cada nó é permanente dentro do Survivor e custa Gold. Evolua caminhos ofensivos, defensivos e utilitários.</div></div><div class="psy22-skilltree" style="margin-top:10px">${Object.entries(defs).map(([k,d],i)=>{const lv=Number(ps.survSkills?.[k]||0),cost=psySkillCost(k,lv),max=lv>=d.max;return`<div class="psy22-node ${max?'max':''}"><img src="${i>=4?shiny:normal}"><h4>${esc(d.n)} • ${lv}/${d.max}</h4><div class="psy20-sub" style="min-height:36px">${esc(d.d)}</div><button class="psy20-btn ${max?'green':'purple'}" style="width:100%;margin-top:7px" ${max?'disabled':''} onclick="v12BuyPsySkill('${esc(k)}')">${max?'MÁXIMO':`${fmt(cost)} Gold`}</button></div>`}).join('')}</div>`};try{v12RenderPsyTree=W.v12RenderPsyTree}catch(e){}
W.v12RenderTrials=function(c){if(!c)return;const ps=psy22TreeState(),p=typeof v12EnsurePsyduck==='function'?v12EnsurePsyduck():null,r=Number(p?.resets||0),best=Number(ps.survivorBest||0),trials=typeof V12_PSY_TRIALS!=='undefined'?V12_PSY_TRIALS:[];c.innerHTML=`<div class="psy20-card"><h3 style="margin:0;color:#facc15">🏆 PROVAÇÕES DA ASCENSÃO</h3><div class="psy20-sub">Cada Provação exige Reset + progresso no Survivor e concede 1 PsyCoin somente na primeira conclusão, além do prêmio de Gold.</div></div><div class="psy20-trials" style="margin-top:9px">${trials.map((need,i)=>{const phase=trialPhase(i),id='t'+(i+1),done=!!ps.trialsDone?.[id],open=r>=need&&best>=phase;return`<div class="psy20-trial ${done?'done':open?'open':''}"><b>Prova ${i+1}</b><div>Reset ${need} • Survivor Fase ${phase}</div><small style="display:block;color:#9bb7da;margin:6px 0">${fmt(trialBaseReward(i))} Gold + 💠 1 PsyCoin${(i+1)%4===0?' + 1 PsyStone':''}${(i+1)%5===0?' + 1 Pack Raro':''}</small><button class="psy20-btn ${open&&!done?'gold':''}" ${!open||done?'disabled':''} onclick="v12ClaimPsyTrial(${i+1})">${done?'CONCLUÍDA':open?'CONCLUIR PROVA':'🔒 BLOQUEADA'}</button></div>`}).join('')}</div>`};try{v12RenderTrials=W.v12RenderTrials}catch(e){}
W.v12RenderSurvZones=function(c){if(!c)return;const ps=psy22TreeState(),best=Number(ps.survivorBest||0),hasSaved=!!W.psySurvHasSavedRun?.(),savedSummary=hasSaved?String(W.psySurvSavedSummary?.()||'Run salva em andamento'):'';const resumeCard=hasSaved?`<div class="psy20-card" style="margin-top:9px;border-color:#38bdf8;background:linear-gradient(135deg,#082f49cc,#0f172acc);box-shadow:0 0 22px #38bdf822"><h3 style="margin:0;color:#7dd3fc">💾 RUN DO SURVIVOR PAUSADA</h3><div class="psy20-sub" style="margin-top:5px">${savedSummary}</div><div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap"><button class="psy20-btn green" onclick="psySurvResumeSaved()">▶ CONTINUAR RUN SALVA</button><button class="psy20-btn" style="background:#991b1b" onclick="psySurvDiscardSaved()">DESCARTAR RUN</button></div><small style="display:block;margin-top:8px;color:#94a3b8">Enquanto esta run estiver salva, iniciar outra fase fica bloqueado para evitar perder o progresso.</small></div>`:'';c.innerHTML=`<div class="psy20-card"><h3 style="margin:0;color:#67e8f9">🎮 PSYDUCK SURVIVOR — 400 FASES</h3><div class="psy20-sub">Run Lv.1 em cada fase. Cada fase dura 10 minutos e a progressão agora vai até a Fase 400. Elites aparecem a cada 1m30; Bosses aos 3, 6 e 9 minutos; Boss final no minuto 10. Você pode pausar uma run, voltar para a Cidade e continuar depois sem perder o progresso.</div></div>${resumeCard}<div class="psy22-zonegrid" style="margin-top:9px">${Array.from({length:400},(_,i)=>{let z;try{z=v12Zone(i)}catch(e){z={i:i+1,name:'Setor '+(i+1),type:'Normal',diff:1+i*.03}}const open=i<=best&&!hasSaved;return`<div class="psy22-zone ${i===best?'current':''}"><b>Fase ${z.i||i+1}: ${esc(z.name||'Setor')}</b><div class="psy20-sub">${esc((typeof V12_TYPE_PT!=='undefined'&&V12_TYPE_PT[z.type])||z.type||'Normal')} • dificuldade x${Number(z.diff||1).toFixed(2)}</div><button class="psy20-btn green" style="width:100%;margin-top:6px" ${!open?'disabled':''} onclick="v12StartSurvivor(${i})">${hasSaved?'💾 RUN SALVA EM ANDAMENTO':i<best?'JOGAR NOVAMENTE':open?'JOGAR':'🔒 BLOQUEADA'}</button></div>`}).join('')}</div>`};try{v12RenderSurvZones=W.v12RenderSurvZones}catch(e){}
W.v12PsyTab=function(tab){const c=$('psy-v12-tab');if(!c)return;D.querySelectorAll('#screen-psyduck-v12 .psy-v12-psy-tabs button').forEach(b=>b.classList.toggle('on',(b.dataset.tab||'')===tab));if(tab==='survivor')return W.v12RenderSurvZones(c);if(tab==='trials')return W.v12RenderTrials(c);if(tab==='tree')return W.v12RenderPsyTree(c);if(tab==='ascend'){try{return typeof v12RenderAscend==='function'?v12RenderAscend(c):null}catch(e){}}c.innerHTML='<div class="psy20-card">Sistema indisponível.</div>'};try{v12PsyTab=W.v12PsyTab}catch(e){}

/* ---------- PsyCoin ? button and global buff strip ---------- */
W.openPsyCoinTutorial=function(){core();let s=$('psy20-psycoin-help');if(!s){s=D.createElement('div');s.id='psy20-psycoin-help';s.className='psy20-overlay';D.body.appendChild(s)}s.style.display='flex';s.innerHTML=`<div class="psy20-panel" style="width:min(760px,96vw)"><button class="psy20-close" onclick="document.getElementById('psy20-psycoin-help').style.display='none'">×</button><h2 class="psy20-title">💠 TUTORIAL — PSYCOIN</h2><div class="psy20-card" style="margin-top:10px"><b>Como conseguir</b><ul class="psy20-sub" style="line-height:1.8"><li><b>Reset do Psyduck:</b> +1 PsyCoin por Reset. Cada novo Reset exige mais EXP para voltar ao Lv.100 e Gold crescente. Provações são um sistema separado e não bloqueiam o Reset.</li><li><b>Loja Premium:</b> na versão online, 1 PsyCoin corresponde conceitualmente a R$1.</li><li><b>Eventos e códigos oficiais:</b> podem conceder PsyCoin.</li></ul></div><div class="psy20-card" style="margin-top:8px"><b>Onde usar</b><div class="psy20-sub">VIP, Passe Premium, compra de XP do Passe e conteúdo premium específico.</div></div></div>`};try{openPsyCoinTutorial=W.openPsyCoinTutorial}catch(e){}
function psy22BuffInfo(kind,source,label,amount,remainingMs){const names={dmg:'ATK',hp:'HP',xp:'XP',gold:'Gold',drop:'Drop',cap:'Captura',crit:'Crítico',shiny:'Shiny'},n=names[kind]||label||kind,a=Number(amount||0);let msg=`📊 ${n} +${a.toFixed(a%1?1:0)}%`;if(source==='world')msg+=`\nOrigem: WORLD — melhoria permanente comprada com Gold.`;else if(source==='trainer')msg+=`\nOrigem: TALENTOS DO TREINADOR — melhoria permanente comprada com pontos de Trainer.`;else if(source==='roulette'){const sec=Math.max(0,Math.ceil(Number(remainingMs||0)/1000)),m=Math.floor(sec/60),ss=sec%60;msg+=`\nOrigem: ROLETA DE JORNADA — buff temporário.\nTempo restante: ${m}:${String(ss).padStart(2,'0')}. Repetições acumulam tempo, não percentual.`}else if(source==='vip')msg+=`\nOrigem: VIP.`;if(typeof notif==='function')notif(msg,6500);else alert(msg)}
W.psy22BuffInfo=psy22BuffInfo;
function psy22BuffStrip(){let h=$('psy22-buffs');if(!h){h=D.createElement('div');h.id='psy22-buffs';h.className='psy22-buffs';D.body.appendChild(h)}
/* Survivor has its own HUD. Never render the global buff strip while a Survivor run exists. */
if(W.PSY_CLEAN_SURV){h.innerHTML='';h.style.setProperty('display','none','important');return}
h.style.removeProperty('display');let temp=[];try{temp=typeof psyV10TickTempBuffs==='function'?psyV10TickTempBuffs():(psyV10RewardsEnsure()?.tempBuffs||[])}catch(e){}const vip={xp:vipOn()?50:0,drop:vipOn()?50:0,cap:vipOn()?20:0};const specs=[['dmg','⚔ ATK'],['hp','❤ HP'],['xp','⭐ XP'],['gold','🪙 GOLD'],['drop','🎁 DROP'],['cap','🎯 CAP'],['crit','💥 CRIT'],['shiny','✨ SHINY']];let tempOut=[],permOut=[];for(const b of temp){const sec=Math.max(0,Math.ceil(Number(b.remainingMs||0)/1000)),m=Math.floor(sec/60),ss=sec%60;tempOut.push(`<span class="psy22-buff temp" title="Clique para ver a origem" onclick="psy22BuffInfo('${b.kind}','roulette','${esc(b.label||b.kind)}',${Number(b.amount||0)},${Number(b.remainingMs||0)})">⏱ ${esc(b.label||b.kind)} ${m}:${String(ss).padStart(2,'0')}</span>`)}for(const [k,l] of specs){const world=Math.max(0,Number(P.worldBuffs?.[k]||0)),trainer=Math.max(0,Number(P.trainerBuffs?.[k]||0));if(world>0)permOut.push(`<span class="psy22-buff" title="Clique para ver a origem" onclick="psy22BuffInfo('${k}','world','${l}',${world},0)">${l} +${world.toFixed(world%1?1:0)}% WORLD</span>`);if(trainer>0)permOut.push(`<span class="psy22-buff" title="Clique para ver a origem" onclick="psy22BuffInfo('${k}','trainer','${l}',${trainer},0)">${l} +${trainer.toFixed(trainer%1?1:0)}% TREINADOR</span>`)}if(vipOn())tempOut.push(`<span class="psy22-buff vip" title="Clique para ver a origem" onclick="psy22BuffInfo('xp','vip','VIP',50,0)">⭐ VIP ${esc(vipRemain())}</span>`);const out=[...tempOut,...permOut];h.innerHTML=out.join('');h.style.display=out.length?'flex':'none';h.style.top='7px';h.style.bottom='auto';h.style.left='50%';h.style.right='auto';h.style.transform='translateX(-50%)';h.style.maxWidth='min(880px,58vw)';h.style.justifyContent='center'}

/* ---------- Gacha: visible pack opening + stable history + duplicate semantics ---------- */
function psy22Entry(x){const id=Number(x?.id??x?.pokeId);if(!Number.isFinite(id)||id<=0)return null;return{id,pokeId:id,variant:x.variant||'normal',sub:x.sub||'',label:x.label||'',copies:Number(x.copies||1),stickerRank:x.stickerRank||x.rank||''}}
function psy22StickerImg(e){const id=Number(e.id),sh=e.variant==='shiny'||e.variant==='mega_shiny'||(e.variant==='psyduck'&&['shiny','mega_shiny','squizo'].includes(e.sub));try{return W.getRealSprite?.({id,shiny:sh,isMega:e.variant==='mega'||e.variant==='mega_shiny'})||`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${sh?'shiny/':''}${id}.png`}catch(x){return`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${sh?'shiny/':''}${id}.png`}}
function psy22StickerName(e){if(e.variant==='psyduck')return e.label||'Psyduck';try{return W.getPokeName?.(e.id)||`Pokémon ${e.id}`}catch(x){return`Pokémon ${e.id}`}}
function psy22OpenResult(items,packName){let s=$('psy22-pack-result');if(!s){s=D.createElement('div');s.id='psy22-pack-result';s.className='psy20-overlay';D.body.appendChild(s)}s.style.display='flex';s.innerHTML=`<div class="psy20-panel" style="width:min(1050px,96vw)"><button class="psy20-close" onclick="document.getElementById('psy22-pack-result').style.display='none'">×</button><h2 class="psy20-title">🎁 ${esc(packName)}</h2><div class="psy20-sub">Figurinhas repetidas aumentam o contador xN da figurinha; apenas a primeira cópia aumenta o total de figurinhas únicas do Álbum.</div><div class="psy22-pullgrid" style="margin-top:10px">${items.map(e=>`<div class="psy22-pull ${e.wasDuplicate?'dup':''}"><img src="${psy22StickerImg(e)}"><b>${esc(psy22StickerName(e))}</b><small>${esc((e.variant||'normal').replaceAll('_',' ').toUpperCase())}</small><div style="color:${e.wasDuplicate?'#f59e0b':'#22c55e'};font-weight:900">${e.wasDuplicate?'REPETIDA • x'+e.copies:'NOVA'}</div></div>`).join('')}</div></div>`}

const PSY55_FUSION_LADDER=['normal','rare','epic','s','ss','sss','ur','urp','urpp'];
function psy55FusionLabel(k){return PACKS20?.[k]?.n||({normal:'Normal',rare:'Raro',epic:'Épico',s:'S',ss:'SS',sss:'SSS',ur:'UR',urp:'UR+',urpp:'UR++'}[k]||String(k).toUpperCase())}
function psy55InferLegacyRank(x){const v=String(x?.variant||'normal');if(v==='psyduck')return'ur';if(v==='mega_shiny')return'sss';if(v==='legendary')return'ss';if(v==='boss')return's';if(v==='mega')return'epic';if(v==='shiny')return'rare';return'normal'}
function psy55FusionEnsure(){core();P.cardGame.fusionLedger=P.cardGame.fusionLedger||{};for(const r of PSY55_FUSION_LADDER)if(!Array.isArray(P.cardGame.fusionLedger[r]))P.cardGame.fusionLedger[r]=[];if(!P.cardGame.fusionMigratedV55){for(const [k,x] of Object.entries(P.cardGame.stickers||{})){const extras=Math.max(0,Number(x?.copies||1)-1),rank=psy55InferLegacyRank(x);for(let i=0;i<extras;i++)P.cardGame.fusionLedger[rank].push(k)}P.cardGame.fusionMigratedV55=1;save()}return P.cardGame.fusionLedger}
function psy55NormalizeFusion(rank){const L=psy55FusionEnsure(),src=L[rank]||[],used={},out=[];for(const key of src){const st=P.cardGame.stickers?.[key],avail=Math.max(0,Number(st?.copies||1)-1),n=Number(used[key]||0);if(st&&n<avail){out.push(key);used[key]=n+1}}L[rank]=out;return out}
function psy55RecordDuplicate(key,rank){if(!key||!PSY55_FUSION_LADDER.includes(rank))return;const L=psy55FusionEnsure();L[rank].push(key);psy55NormalizeFusion(rank)}
function psy55FusionStock(rank){return psy55NormalizeFusion(rank).length}
function psy55FusionPanel(){psy55FusionEnsure();return `<div class="psy15-panel" style="margin-top:12px"><div class="psy20-row"><div><h3 style="margin:0;color:#facc15">🧬 FUSÃO DE FIGURINHAS REPETIDAS</h3><div class="psy20-sub">A cada <b>5 cópias repetidas</b> de uma raridade, você pode criar <b>1 figurinha da raridade imediatamente superior</b>. A primeira cópia da coleção nunca é consumida.</div></div></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px;margin-top:10px">${PSY55_FUSION_LADDER.slice(0,-1).map((r,i)=>{const next=PSY55_FUSION_LADDER[i+1],n=psy55FusionStock(r);return `<div class="psy20-card" style="text-align:center"><b>${esc(psy55FusionLabel(r))} → ${esc(psy55FusionLabel(next))}</b><div style="font-size:22px;font-weight:1000;color:${n>=5?'#4ade80':'#facc15'};margin:7px 0">${n}/5</div><button class="psy20-btn ${n>=5?'green':''}" style="width:100%" ${n<5?'disabled':''} onclick="psy55FuseStickers('${r}')">FUNDIR 5</button></div>`}).join('')}</div><div class="psy20-sub" style="margin-top:8px">UR++ é o teto da fusão e não possui raridade acima.</div></div>`}
W.psy55FuseStickers=function(rank){core();rank=String(rank);const idx=PSY55_FUSION_LADDER.indexOf(rank),next=PSY55_FUSION_LADDER[idx+1];if(idx<0||!next)return toast('Esta raridade já está no máximo.');const led=psy55NormalizeFusion(rank);if(led.length<5)return toast(`Precisa de 5 repetidas ${psy55FusionLabel(rank)}.`);const used=led.splice(0,5);for(const key of used){const st=P.cardGame.stickers?.[key];if(st)st.copies=Math.max(1,Number(st.copies||1)-1)}let raw=null;for(let t=0;t<8&&!raw;t++)raw=psy22Entry(rollSticker20(next));if(!raw){for(const key of used){const st=P.cardGame.stickers?.[key];if(st)st.copies=Number(st.copies||1)+1}psy55FusionEnsure()[rank].unshift(...used);return toast('Falha ao gerar a fusão. Nenhuma figurinha foi consumida.')}raw.stickerRank=next;const sk=stickerKey(raw),before=Number(P.cardGame.stickers?.[sk]?.copies||0),stored=addSticker(raw);if(before>0)psy55RecordDuplicate(sk,next);const result={...raw,copies:Number(stored.copies||1),wasDuplicate:before>0};P.cardGame.fusionHistory=P.cardGame.fusionHistory||[];P.cardGame.fusionHistory.unshift({when:Date.now(),from:rank,to:next,item:{...result}});P.cardGame.fusionHistory=P.cardGame.fusionHistory.slice(0,30);save();psy22OpenResult([result],`FUSÃO ${psy55FusionLabel(rank)} → ${psy55FusionLabel(next)}`);W.renderCardTab?.('gacha')};try{psy55FuseStickers=W.psy55FuseStickers}catch(e){}
W.cgOpenPack=function(k){
  core();
  const x=PACKS20[k],owned=Number(P.cardGame.packs[k]||0);
  if(!x||owned<=0)return toast('Você não possui este Pack.');
  const pulls=[];
  for(let i=0;i<x.qty;i++){
    let raw=null;
    for(let tries=0;tries<5&&!raw;tries++)raw=psy22Entry(rollSticker20(k));
    if(!raw)continue;
    const key=stickerKey(raw),before=Number(P.cardGame.stickers[key]?.copies||0),stored=addSticker(raw),e={...raw,copies:Number(stored.copies||1),wasDuplicate:before>0};
    pulls.push(e);
  }
  if(!pulls.length){
    console.error('Pack sem resultados válidos',k,{ids:allIds().length,legendarios:legs().length,megas:megas().length});
    return toast('Falha ao gerar as figurinhas. O Pack não foi consumido.');
  }
  P.cardGame.packs[k]=Math.max(0,owned-1);
  P.cardGame.lastPack=pulls;
  P.cardGame.stickerHistory.unshift({when:Date.now(),pack:k,name:x.n,items:pulls.map(v=>({...v}))});
  P.cardGame.stickerHistory=P.cardGame.stickerHistory.slice(0,20);
  save();
  psy22OpenResult(pulls,x.n);
  W.renderCardTab?.('gacha');
};
try{cgOpenPack=W.cgOpenPack}catch(e){}
const psy22CardBase=W.renderCardTab;
W.renderCardTab=function(tab){
  if(tab==='history'){
    core();const host=$('cg-content');if(!host)return;try{if(typeof side==='function')side('history','all')}catch(e){}
    const hist=(P.cardGame.stickerHistory||[]).map(h=>({...h,items:(h.items||[]).map(psy22Entry).filter(Boolean)})).filter(h=>h.items.length);
    host.innerHTML=`<div class="psy15-panel"><h2 style="margin:0">📜 HISTÓRICO DE PACKS</h2><div class="psy20-sub">Somente aberturas válidas são exibidas. Repetidas aparecem com seu contador de cópias.</div></div>${hist.length?hist.map(h=>`<div class="psy22-history-block"><div class="psy20-row"><b>${esc(h.name||h.pack||'Pack')}</b><small>${new Date(h.when||Date.now()).toLocaleString('pt-BR')}</small></div><div class="psy22-pullgrid" style="margin-top:8px">${h.items.map(e=>`<div class="psy22-pull"><img src="${psy22StickerImg(e)}"><b>${esc(psy22StickerName(e))}</b><small>${esc((e.variant||'normal').replaceAll('_',' ').toUpperCase())} • x${Number(e.copies||1)}</small></div>`).join('')}</div></div>`).join(''):'<div class="psy20-card" style="margin-top:10px">Nenhum pack válido aberto ainda.</div>'}`;return
  }
  const r=psy22CardBase?.apply(this,arguments);
  if(tab==='gacha'){core();const host=$('cg-content');if(host)host.insertAdjacentHTML('beforeend',psy55FusionPanel())}
  return r
};
